/* D1 · LO 1.1–1.2 — more written questions: anatomy, hazards, approaches, planting material, soil and water, harvest (chapters d1a, d1b) */
const { G } = require("../_guide.js");
const P = (t, m, k, a) => ({ t, m, k, a });
const Q = (c, q, parts) => ({ c, q, g: G(parts.map(p => p.m)), parts });
module.exports = {
  open: [
    Q("d1a", ["La vite, dal ceppo all'acino.", "La vigne, du cep à la baie.", "The vine, from trunk to berry.", "La vid, del tronco a la baya."], [
      P(["Descrivi le parti della vite e la funzione di ciascuna nella produzione dell'uva.", "Décrivez les parties de la vigne et le rôle de chacune dans la production du raisin.", "Describe the parts of the vine and the role of each in producing grapes.", "Describe las partes de la vid y la función de cada una en la producción de uva."], 7,
        ["gemme composte: si formano in una stagione e germogliano la successiva, gemma primaria con secondaria e terziaria di riserva dopo una gelata; gemme pronte e femminelle: crescono nello stesso anno, foglie in più ma ombra, possibile seconda vendemmia meno matura; foglie: fotosintesi, stomi, traspirazione che richiama acqua e nutrienti; viticci per sostenersi, ma i tralci si legano al filo; legno di un anno, tralcio o sperone, porta le gemme della stagione; legno permanente, tronco e cordoni: sostegno, trasporto, riserve di carboidrati; radici: ancoraggio, assorbimento di acqua e nutrienti, riserve e ormoni, soprattutto nei primi 50 cm",
         "bourgeons composés : formés une saison, ils débourrent la suivante, bourgeon principal avec secondaire et tertiaire de réserve après un gel ; prompt-bourgeons et entre-cœurs : poussent la même année, feuilles en plus mais ombre, possible seconde récolte moins mûre ; feuilles : photosynthèse, stomates, transpiration qui fait monter eau et nutriments ; vrilles pour s'accrocher, mais on attache les sarments au fil ; bois d'un an, long bois ou courson, porte les bourgeons de la saison ; bois permanent, tronc et cordons : soutien, transport, réserves de glucides ; racines : ancrage, absorption de l'eau et des nutriments, réserves et hormones, surtout dans les 50 premiers cm",
         "compound buds: form in one season and burst the next, primary bud with secondary and tertiary as back-up after frost; prompt buds and laterals: grow the same year, extra leaves but shade, possible second crop that is less ripe; leaves: photosynthesis, stomata, transpiration that draws up water and nutrients; tendrils for support, though shoots are tied to the wires; one-year-old wood, cane or spur, carries the buds for the season; permanent wood, trunk and cordons: support, transport, carbohydrate reserves; roots: anchorage, uptake of water and nutrients, reserves and hormones, mostly in the top 50 cm",
         "yemas compuestas: se forman en una temporada y brotan la siguiente, yema principal con secundaria y terciaria de reserva tras una helada; yemas prontas y nietos: crecen el mismo año, más hojas pero sombra, posible segunda cosecha menos madura; hojas: fotosíntesis, estomas, transpiración que hace subir agua y nutrientes; zarcillos para sujetarse, aunque los brotes se atan al alambre; madera de un año, vara o pulgar, lleva las yemas de la temporada; madera permanente, tronco y brazos: sostén, transporte, reservas de carbohidratos; raíces: anclaje, absorción de agua y nutrientes, reservas y hormonas, sobre todo en los primeros 50 cm"],
        ["Le gemme composte si formano alla base del picciolo durante una stagione e germogliano in quella successiva, se sopravvivono alla potatura: contengono una gemma primaria e gemme secondarie e terziarie che partono solo se la primaria è danneggiata, per esempio da una gelata, dando germogli meno fertili. Le gemme pronte germogliano nello stesso anno e danno le femminelle: offrono foglie in più se sono ben esposte, ma vicino ai grappoli ombreggiano e ostacolano l'aria, e i loro grappoli (la «seconda vendemmia») maturano più tardi. Le foglie sono la sede della fotosintesi: dagli stomi entra la CO₂ ed esce acqua, e questa traspirazione richiama acqua e nutrienti dal suolo; con lo stress idrico gli stomi si chiudono e la fotosintesi rallenta. I viticci servono ad aggrapparsi, ma il viticoltore lega comunque tralci e germogli. Il legno di un anno, lasciato con la potatura come tralcio o sperone, porta le gemme della stagione; il legno permanente, tronco ed eventuali cordoni, sostiene la pianta, trasporta acqua e soluti e immagazzina carboidrati e nutrienti. Le radici ancorano la vite, assorbono acqua e nutrienti dalle punte in crescita, accumulano riserve e producono ormoni; la maggior parte sta nei primi 50 cm, ma alcune scendono oltre i sei metri. Di solito la vite è innestata su un portinnesto.",
         "Les bourgeons composés se forment à la base du pétiole au cours d'une saison et débourrent la suivante, s'ils sont conservés à la taille : ils contiennent un bourgeon principal et des bourgeons secondaires et tertiaires qui ne partent que si le principal est endommagé, par exemple par un gel, en donnant des rameaux moins fertiles. Les prompt-bourgeons débourrent la même année et donnent les entre-cœurs : ils apportent des feuilles en plus s'ils sont bien exposés, mais près des grappes ils font de l'ombre et gênent l'aération, et leurs grappes (la « seconde récolte ») mûrissent plus tard. Les feuilles sont le siège de la photosynthèse : par les stomates entre le CO₂ et sort l'eau, et cette transpiration fait monter l'eau et les nutriments du sol ; en stress hydrique les stomates se ferment et la photosynthèse ralentit. Les vrilles servent à s'accrocher, mais le viticulteur attache tout de même sarments et rameaux. Le bois d'un an, conservé à la taille en long bois ou en courson, porte les bourgeons de la saison ; le bois permanent, tronc et éventuels cordons, soutient la plante, transporte eau et solutés et stocke glucides et nutriments. Les racines ancrent la vigne, absorbent eau et nutriments par leurs extrémités en croissance, accumulent des réserves et produisent des hormones ; la plupart se trouvent dans les 50 premiers centimètres, mais certaines descendent à plus de six mètres. La vigne est en général greffée sur un porte-greffe.",
         "Compound buds form at the base of the leaf stalk during one season and burst the next, if they are kept at pruning: they contain a primary bud and secondary and tertiary buds that grow only if the primary is damaged, for example by frost, giving less fruitful shoots. Prompt buds burst in the same year and give lateral shoots: these add leaves if well exposed, but near the bunches they shade the fruit and block air flow, and their bunches (the 'second crop') ripen later. Leaves are the site of photosynthesis: carbon dioxide enters through the stomata and water leaves, and this transpiration draws water and nutrients up from the soil; under water stress the stomata close and photosynthesis slows. Tendrils allow the vine to cling, but growers still tie in canes and shoots. One-year-old wood, kept at pruning as a cane or a spur, carries the buds for the coming season; permanent wood, the trunk and any cordons, supports the plant, transports water and solutes and stores carbohydrates and nutrients. Roots anchor the vine, absorb water and nutrients at their growing tips, store reserves and produce hormones; most are in the top 50 cm, though some reach more than six metres down. The vine is usually grafted onto a rootstock.",
         "Las yemas compuestas se forman en la base del peciolo durante una temporada y brotan la siguiente, si se conservan en la poda: contienen una yema principal y yemas secundarias y terciarias que solo brotan si la principal se daña, por ejemplo por una helada, dando brotes menos fértiles. Las yemas prontas brotan el mismo año y dan los nietos: aportan hojas extra si están bien expuestos, pero junto a los racimos dan sombra y frenan la aireación, y sus racimos (la «segunda cosecha») maduran más tarde. Las hojas son la sede de la fotosíntesis: por los estomas entra el CO₂ y sale agua, y esa transpiración hace subir agua y nutrientes del suelo; con estrés hídrico los estomas se cierran y la fotosíntesis se frena. Los zarcillos sirven para agarrarse, pero el viticultor ata igualmente varas y brotes. La madera de un año, que se deja en la poda como vara o pulgar, lleva las yemas de la temporada; la madera permanente, el tronco y los posibles brazos, sostiene la planta, transporta agua y solutos y almacena carbohidratos y nutrientes. Las raíces anclan la vid, absorben agua y nutrientes por las puntas en crecimiento, acumulan reservas y producen hormonas; la mayoría está en los primeros 50 cm, aunque algunas bajan a más de seis metros. Normalmente la vid está injertada sobre un portainjerto."]),
      P(["Spiega come cambiano zuccheri, acidi, colore, tannini e composti aromatici dell'acino dalla formazione alla sovramaturazione.", "Expliquez comment évoluent sucres, acides, couleur, tanins et composés aromatiques de la baie, de sa formation à la surmaturation.", "Explain how the sugars, acids, colour, tannins and aroma compounds of the berry change from formation to extra-ripening.", "Explica cómo cambian azúcares, ácidos, color, taninos y compuestos aromáticos de la baya desde su formación hasta la sobremaduración."], 8,
        ["formazione: acini verdi, si accumulano acido tartarico e malico, zucchero basso; tannini amari e metossipirazine erbacee si formano presto; invaiatura: la clorofilla si degrada, le uve nere sintetizzano antociani; maturazione: zucchero e acqua entrano con il floema, più veloci con caldo e asciutto; il tartarico si diluisce, il malico cala con la respirazione, più in fretta oltre 21 °C; le metossipirazine calano, i terpeni e altri precursori aumentano; i tannini polimerizzano e diventano meno amari, antociani favoriti da luce e 15–25 °C; sovramaturazione: l'acino perde acqua, lo zucchero si concentra, aromi molto maturi",
         "formation : baies vertes, accumulation d'acides tartrique et malique, sucre faible ; tanins amers et méthoxypyrazines herbacées se forment tôt ; véraison : la chlorophylle se dégrade, les raisins noirs synthétisent les anthocyanes ; maturation : sucre et eau arrivent par le phloème, plus vite par temps chaud et sec ; le tartrique se dilue, le malique baisse par la respiration, plus vite au-delà de 21 °C ; les méthoxypyrazines baissent, terpènes et autres précurseurs augmentent ; les tanins polymérisent et deviennent moins amers, anthocyanes favorisées par la lumière et 15–25 °C ; surmaturation : la baie perd de l'eau, le sucre se concentre, arômes très mûrs",
         "formation: green berries, tartaric and malic acid accumulate, low sugar; bitter tannins and herbaceous methoxypyrazines form early; véraison: chlorophyll breaks down, black grapes synthesise anthocyanins; ripening: sugar and water arrive via the phloem, faster in warm dry weather; tartaric is diluted, malic falls through respiration, faster above 21 °C; methoxypyrazines fall, terpenes and other precursors rise; tannins polymerise and become less bitter, anthocyanins favoured by light and 15–25 °C; extra-ripening: the berry loses water, sugar concentrates, very ripe aromas",
         "formación: bayas verdes, se acumulan ácido tartárico y málico, poco azúcar; taninos amargos y metoxipirazinas herbáceas se forman pronto; envero: la clorofila se degrada, las uvas tintas sintetizan antocianos; maduración: azúcar y agua llegan por el floema, más rápido con calor y sequedad; el tartárico se diluye, el málico baja por la respiración, más deprisa por encima de 21 °C; las metoxipirazinas bajan, terpenos y otros precursores suben; los taninos polimerizan y se vuelven menos amargos, antocianos favorecidos por la luz y 15–25 °C; sobremaduración: la baya pierde agua, el azúcar se concentra, aromas muy maduros"],
        ["Dopo l'allegagione gli acini verdi e duri crescono e accumulano acido tartarico e malico; lo zucchero resta basso. Si formano già alcuni composti aromatici e precursori, come le metossipirazine dalle note erbacee, e i tannini, ancora molto amari; il sole sui grappoli favorisce l'accumulo dei tannini. Troppa acqua e azoto prolungano questa fase a favore della vegetazione. All'invaiatura la crescita si ferma per qualche giorno, la clorofilla si degrada e nelle uve nere compaiono gli antociani. Durante la maturazione l'acino si espande: zucchero e acqua arrivano con il floema e l'accumulo è più rapido con tempo caldo e asciutto, a volte troppo, prima che aromi e tannini siano maturi. La quantità di tartarico non cambia ma si diluisce; il malico cala di più perché viene consumato nella respirazione, tanto più in fretta quanto più fa caldo (oltre 21 °C di media nell'ultimo mese) e meno con notti fresche. Le metossipirazine diminuiscono, salvo con freddo e ombra, mentre aumentano terpeni e altri precursori. Nei rossi i tannini polimerizzano e diventano meno amari, aiutati dalla luce; gli antociani aumentano soprattutto con molta luce e 15–25 °C. Se l'uva resta sulla pianta, l'acino non riceve più zucchero né acqua ma perde acqua per traspirazione: lo zucchero si concentra e compaiono aromi di frutta molto matura o appassita, utili per alcuni stili e non per altri.",
         "Après la nouaison, les baies vertes et dures grossissent et accumulent acides tartrique et malique ; le sucre reste bas. Certains composés aromatiques et précurseurs se forment déjà, comme les méthoxypyrazines aux notes herbacées, ainsi que les tanins, encore très amers ; le soleil sur les grappes favorise leur accumulation. Trop d'eau et d'azote prolongent cette phase au profit de la végétation. À la véraison, la croissance s'arrête quelques jours, la chlorophylle se dégrade et les anthocyanes apparaissent dans les raisins noirs. Pendant la maturation, la baie grossit : sucre et eau arrivent par le phloème et l'accumulation est plus rapide par temps chaud et sec, parfois trop, avant que arômes et tanins soient mûrs. La quantité de tartrique ne change pas mais se dilue ; le malique baisse davantage car il est consommé par la respiration, d'autant plus vite qu'il fait chaud (plus de 21 °C de moyenne le dernier mois) et moins avec des nuits fraîches. Les méthoxypyrazines diminuent, sauf par temps frais et à l'ombre, tandis qu'augmentent terpènes et autres précurseurs. Dans les rouges, les tanins polymérisent et deviennent moins amers, aidés par la lumière ; les anthocyanes augmentent surtout avec beaucoup de lumière et 15–25 °C. Si le raisin reste sur pied, la baie ne reçoit plus ni sucre ni eau mais perd de l'eau par transpiration : le sucre se concentre et des arômes de fruit très mûr ou séché apparaissent, utiles pour certains styles et pas pour d'autres.",
         "After fruit set, the hard green berries grow and accumulate tartaric and malic acid; sugar stays low. Some aroma compounds and precursors already form, such as herbaceous methoxypyrazines, as do tannins, which are still very bitter; sunshine on the bunches promotes tannin build-up. Too much water and nitrogen prolong this stage in favour of shoot growth. At véraison growth pauses for a few days, chlorophyll breaks down and anthocyanins appear in black grapes. During ripening the berry expands: sugar and water arrive via the phloem and accumulation is faster in warm, dry weather, sometimes too fast, before aromas and tannins are ripe. The amount of tartaric acid does not change but is diluted; malic acid falls further because it is used up in respiration, faster the warmer it is (mean temperatures above 21 °C in the final month) and less with cool nights. Methoxypyrazines decrease, except in cool, shaded conditions, while terpenes and other precursors increase. In black grapes tannins polymerise and become less bitter, helped by sunlight; anthocyanins increase most with plentiful light and 15–25 °C. If the grapes are left on the vine, the berry receives no more sugar or water but loses water by transpiration: sugar concentrates and very ripe or dried fruit aromas appear, desirable in some styles and not in others.",
         "Tras el cuajado, las bayas verdes y duras crecen y acumulan ácido tartárico y málico; el azúcar sigue bajo. Ya se forman algunos compuestos aromáticos y precursores, como las metoxipirazinas de notas herbáceas, y los taninos, todavía muy amargos; el sol sobre los racimos favorece su acumulación. Demasiada agua y nitrógeno prolongan esta fase en favor de la vegetación. En el envero el crecimiento se detiene unos días, la clorofila se degrada y aparecen los antocianos en las uvas tintas. Durante la maduración la baya se expande: azúcar y agua llegan por el floema y la acumulación es más rápida con tiempo cálido y seco, a veces demasiado, antes de que aromas y taninos maduren. La cantidad de tartárico no cambia pero se diluye; el málico baja más porque se consume en la respiración, tanto más rápido cuanto más calor hace (más de 21 °C de media en el último mes) y menos con noches frescas. Las metoxipirazinas disminuyen, salvo con frío y sombra, mientras aumentan terpenos y otros precursores. En las tintas los taninos polimerizan y se vuelven menos amargos, ayudados por la luz; los antocianos aumentan sobre todo con mucha luz y 15–25 °C. Si la uva se queda en la cepa, la baya ya no recibe azúcar ni agua pero pierde agua por transpiración: el azúcar se concentra y aparecen aromas de fruta muy madura o pasificada, deseables en algunos estilos y no en otros."])]),
    Q("d1a", ["Gelo, grandine, sole e fuoco possono compromettere un'intera annata.", "Gel, grêle, soleil et feu peuvent compromettre tout un millésime.", "Frost, hail, sun and fire can compromise a whole vintage.", "Helada, granizo, sol y fuego pueden comprometer toda una añada."], [
      P(["Spiega i rischi di gelo invernale, gelate primaverili e grandine e le possibili misure di prevenzione e di difesa, con i loro costi.", "Expliquez les risques du gel d'hiver, des gelées de printemps et de la grêle, ainsi que les mesures de prévention et de lutte possibles, avec leurs coûts.", "Explain the risks of winter freeze, spring frost and hail, and the possible preventive and protective measures, with their costs.", "Explica los riesgos de las heladas invernales, las heladas primaverales y el granizo, y las posibles medidas de prevención y protección, con sus costes."], 8,
        ["gelo invernale sotto −20 °C: danni a innesto, tralci e cordoni, anche morte della vite, climi molto continentali; difese: pendii, vicinanza a grandi laghi, neve, varietà e ibridi resistenti, rincalzatura, interramento costoso, più tronchi; gelata primaverile dopo il germogliamento uccide gemme e germogli, le gemme secondarie sono meno fertili; gelate per avvezione da masse d'aria fredda, per irraggiamento nelle notti calme e serene, l'aria fredda si raccoglie in basso; prevenzione: evitare le sacche di gelo, potatura tardiva, varietà a germogliamento tardivo, allevamento alto, suolo nudo; aspersione: il ghiaccio libera calore, unica difesa contro le gelate per avvezione, costo dell'acqua; ventilatori con inversione termica, investimento alto, elicotteri; bruciatori e candele: combustibile e lavoro costosi, poco efficienti; grandine: lacera germogli e foglie, ferisce gli acini, botrite, effetti anche l'anno dopo; difese: reti nella zona dei grappoli dove c'è molta luce, razzi, parcelle in zone diverse, assicurazione",
         "gel d'hiver sous −20 °C : dégâts au point de greffe, aux sarments et aux cordons, voire mort de la vigne, climats très continentaux ; parades : coteaux, proximité de grands lacs, neige, cépages et hybrides résistants, buttage, enfouissement coûteux, plusieurs troncs ; gelée de printemps après le débourrement : tue bourgeons et jeunes pousses, les bourgeons secondaires sont moins fertiles ; gelées d'advection par des masses d'air froid, de radiation par nuits calmes et claires, l'air froid s'accumule en bas ; prévention : éviter les poches de gel, taille tardive, cépages à débourrement tardif, conduite haute, sol nu ; aspersion : la glace libère de la chaleur, seule parade contre les gelées d'advection, coût de l'eau ; tours antigel avec inversion thermique, gros investissement, hélicoptères ; chaufferettes et bougies : combustible et travail coûteux, peu efficaces ; grêle : déchire pousses et feuilles, blesse les baies, botrytis, effets aussi l'année suivante ; parades : filets dans la zone des grappes là où la lumière abonde, fusées, parcelles dispersées, assurance",
         "winter freeze below −20 °C: damage to the graft, canes and cordons, even vine death, strongly continental climates; responses: slopes, nearness to large lakes, snow cover, hardy varieties and hybrids, hilling up, costly burying, several trunks; spring frost after budburst kills buds and young shoots, secondary buds are less fruitful; advective frost from masses of cold air, radiative frost on still clear nights, cold air collects low down; prevention: avoid frost pockets, late pruning, late-budding varieties, high training, bare soil; sprinklers: freezing water releases heat, the only defence against advective frost, cost of water; wind machines with an inversion layer, high investment, helicopters; heaters and candles: costly fuel and labour, inefficient; hail: tears shoots and leaves, damages berries, botrytis, effects into the next season; responses: netting over the fruit zone where sunlight is high, rockets, plots in different areas, insurance",
         "helada invernal por debajo de −20 °C: daños en el injerto, varas y brazos, incluso muerte de la cepa, climas muy continentales; respuestas: laderas, cercanía a grandes lagos, nieve, variedades e híbridos resistentes, aporcado, enterrado costoso, varios troncos; helada primaveral tras la brotación: mata yemas y brotes, las yemas secundarias son menos fértiles; heladas de advección por masas de aire frío, de radiación en noches calmas y despejadas, el aire frío se acumula abajo; prevención: evitar las bolsas de frío, poda tardía, variedades de brotación tardía, conducción alta, suelo desnudo; aspersión: el hielo libera calor, única defensa contra las heladas de advección, coste del agua; torres de ventilación con inversión térmica, inversión alta, helicópteros; quemadores y velas: combustible y mano de obra caros, poco eficaces; granizo: desgarra brotes y hojas, hiere las bayas, botritis, efectos también al año siguiente; respuestas: mallas en la zona de racimos donde hay mucha luz, cohetes, parcelas en zonas distintas, seguros"],
        ["Le viti in riposo sopportano bene il freddo, ma sotto i −20 °C il gelo invernale può danneggiare il punto d'innesto, poi tralci e cordoni, e uccidere la parte aerea, nei climi molto continentali come parti del Canada. Si scelgono pendii, che possono essere fino a 5 °C più caldi del fondovalle, siti vicini a grandi laghi, zone dove la neve si accumula e isola, varietà resistenti o ibridi con specie americane o asiatiche; si rincalza terra sull'innesto, si interrano le viti nei casi estremi, con un costo di manodopera enorme, o si allevano più tronchi. Le gelate primaverili colpiscono dopo il germogliamento: gemme e germogli ricchi d'acqua muoiono, e i germogli delle gemme secondarie sono meno fertili e maturano più tardi. Le gelate per avvezione arrivano con masse d'aria fredda; quelle per irraggiamento nascono nelle notti calme e serene, quando l'aria fredda, più densa, ristagna in basso. Si previene evitando le sacche di gelo, potando tardi per ritardare il germogliamento, scegliendo varietà tardive come il Riesling, allevando alto e lasciando il suolo nudo che rilascia calore di notte. Per difendersi si usano l'aspersione, che sfrutta il calore liberato dall'acqua che gela ed è l'unico metodo contro l'avvezione, ma costa acqua; i ventilatori, che riportano a terra l'aria più calda di un'inversione termica, con un investimento alto; elicotteri; bruciatori e candele, costosi e poco efficienti. La grandine strappa germogli e foglie e ferisce gli acini, aprendo la strada alla botrite, con effetti anche sull'annata seguente; si difende con reti sulla zona dei grappoli, adatte solo dove la luce è abbondante come a Mendoza, con razzi che seminano le nubi, con parcelle in zone diverse e con l'assicurazione.",
         "Les vignes en repos supportent bien le froid, mais sous −20 °C le gel d'hiver peut endommager le point de greffe, puis sarments et cordons, et tuer la partie aérienne, dans les climats très continentaux comme certaines régions du Canada. On choisit des coteaux, qui peuvent être jusqu'à 5 °C plus chauds que le fond de vallée, des sites proches de grands lacs, des zones où la neige s'accumule et isole, des cépages résistants ou des hybrides d'espèces américaines ou asiatiques ; on butte la terre sur la greffe, on enfouit les vignes dans les cas extrêmes, au prix d'un travail énorme, ou l'on conduit plusieurs troncs. Les gelées de printemps frappent après le débourrement : bourgeons et jeunes pousses gorgés d'eau meurent, et les rameaux des bourgeons secondaires sont moins fertiles et mûrissent plus tard. Les gelées d'advection arrivent avec des masses d'air froid ; celles de radiation naissent par nuits calmes et claires, quand l'air froid, plus dense, stagne en bas. On prévient en évitant les poches de gel, en taillant tard pour retarder le débourrement, en choisissant des cépages tardifs comme le Riesling, en conduisant haut et en laissant le sol nu qui restitue la chaleur la nuit. Pour lutter, on recourt à l'aspersion, qui exploite la chaleur libérée par l'eau qui gèle et seule méthode contre l'advection, mais qui coûte de l'eau ; aux tours antigel, qui rabattent l'air plus chaud d'une inversion thermique, au prix d'un lourd investissement ; aux hélicoptères ; aux chaufferettes et bougies, coûteuses et peu efficaces. La grêle déchire pousses et feuilles et blesse les baies, ouvrant la porte au botrytis, avec des effets jusqu'au millésime suivant ; on s'en protège par des filets sur la zone des grappes, adaptés seulement là où la lumière abonde comme à Mendoza, par des fusées qui ensemencent les nuages, par des parcelles dispersées et par l'assurance.",
         "Dormant vines tolerate cold well, but below −20 °C winter freeze can damage the graft union, then canes and cordons, and kill everything above ground, in strongly continental climates such as parts of Canada. Growers choose slopes, which can be up to 5 °C warmer than the valley floor, sites near large lakes, places where snow settles and insulates, hardy varieties or hybrids with American or Asian parentage; they hill up soil over the graft, bury vines in the most extreme climates at enormous labour cost, or train several trunks. Spring frost strikes after budburst: buds and young shoots full of water are killed, and shoots from secondary buds are less fruitful and ripen later. Advective frost arrives with masses of cold air; radiative frost forms on still, clear nights, when dense cold air settles low down. Prevention means avoiding frost pockets, pruning late to delay budburst, choosing late-budding varieties such as Riesling, training high and keeping bare soil that releases heat at night. Protection includes sprinklers, which exploit the heat released as water freezes and are the only method against advective frost, but cost water; wind machines, which pull down warmer air from an inversion layer, at high investment; helicopters; and heaters and candles, costly and inefficient. Hail tears shoots and leaves and damages berries, opening the way to botrytis, with effects into the following season; protection comes from netting the fruit zone, suitable only where sunlight is plentiful, as in Mendoza, from rockets that seed the clouds, from owning plots in different areas and from insurance.",
         "Las cepas en reposo toleran bien el frío, pero por debajo de −20 °C la helada invernal puede dañar el injerto, luego varas y brazos, y matar la parte aérea, en climas muy continentales como zonas de Canadá. Se eligen laderas, que pueden estar hasta 5 °C más cálidas que el fondo del valle, sitios cerca de grandes lagos, zonas donde la nieve se acumula y aísla, variedades resistentes o híbridos con especies americanas o asiáticas; se aporca tierra sobre el injerto, se entierran las cepas en los casos extremos, con un enorme coste de mano de obra, o se conducen varios troncos. Las heladas primaverales llegan tras la brotación: yemas y brotes cargados de agua mueren, y los brotes de las yemas secundarias son menos fértiles y maduran más tarde. Las heladas de advección llegan con masas de aire frío; las de radiación se forman en noches calmas y despejadas, cuando el aire frío, más denso, se estanca abajo. Se previenen evitando las bolsas de frío, podando tarde para retrasar la brotación, eligiendo variedades tardías como el Riesling, conduciendo alto y dejando el suelo desnudo, que libera calor por la noche. Para defenderse se usan la aspersión, que aprovecha el calor que libera el agua al helarse y es el único método contra la advección, pero cuesta agua; las torres de ventilación, que bajan el aire más cálido de una inversión térmica, con una inversión alta; helicópteros; y quemadores y velas, caros y poco eficaces. El granizo desgarra brotes y hojas y hiere las bayas, lo que abre paso a la botritis, con efectos incluso en la añada siguiente; se combate con mallas sobre la zona de racimos, adecuadas solo donde hay mucha luz como en Mendoza, con cohetes que siembran las nubes, con parcelas en zonas distintas y con seguros."]),
      P(["Spiega come scottature, incendi e fumo influiscono sulle uve e sul vino e come si possono limitare.", "Expliquez comment les brûlures, les incendies et la fumée affectent les raisins et le vin, et comment les limiter.", "Explain how sunburn, fire and smoke affect the grapes and the wine and how they can be limited.", "Explica cómo las quemaduras de sol, los incendios y el humo afectan a la uva y al vino y cómo pueden limitarse."], 7,
        ["scottature: l'acino traspira poco e si scalda più della foglia, rischio maggiore con stress idrico; cicatrici, imbrunimento, amaro, marciume, cernita e resa più bassa; prevenzione: orientamento dei filari e esposizione, ombra con la gestione della chioma, irrigazione prima di un'ondata di calore, protezioni solari e reti ombreggianti; incendi più frequenti con il cambiamento climatico, vicino a boschi e pascoli, cover crop e pacciame come combustibile; fumo da invaiatura in poi: composti assorbiti dalle bucce, legati agli zuccheri come precursori senza odore; note affumicate o di plastica che compaiono con la fermentazione e aumentano con l'invecchiamento; analisi e microvinificazioni prima della vendemmia; vendemmia a mano, pressatura delicata o a grappolo intero, fermentazione più fresca, macerazione breve; flash détente e osmosi inversa aiutano ma non eliminano il difetto",
         "brûlures : la baie transpire peu et chauffe plus que la feuille, risque accru en stress hydrique ; cicatrices, brunissement, amertume, pourriture, tri et rendement plus bas ; prévention : orientation des rangs et exposition, ombre par la conduite du feuillage, irrigation avant une canicule, écrans solaires et filets d'ombrage ; incendies plus fréquents avec le changement climatique, près des bois et des pâturages, couverts végétaux et paillis comme combustible ; fumée à partir de la véraison : composés absorbés par les pellicules, liés aux sucres en précurseurs inodores ; notes fumées ou de plastique qui apparaissent à la fermentation et augmentent avec le vieillissement ; analyses et microvinifications avant la vendange ; vendange manuelle, pressurage doux ou en grappes entières, fermentation plus fraîche, macération courte ; flash détente et osmose inverse aident mais n'éliminent pas le défaut",
         "sunburn: the berry transpires little and heats up more than the leaf, greater risk under water stress; scars, browning, bitterness, rot, sorting and lower yield; prevention: row orientation and aspect, shade through canopy management, irrigation before a heatwave, sunscreen sprays and shade cloth; fires more frequent with climate change, near woodland and pasture, cover crops and mulch as fuel; smoke from véraison onwards: compounds absorbed by the skins, bound to sugars as odourless precursors; smoky or plastic notes that appear with fermentation and grow with ageing; analysis and micro-vinifications before harvest; hand picking, gentle or whole bunch pressing, cooler fermentation, short maceration; flash détente and reverse osmosis help but do not remove the taint",
         "quemaduras: la baya transpira poco y se calienta más que la hoja, mayor riesgo con estrés hídrico; cicatrices, pardeamiento, amargor, podredumbre, selección y menor rendimiento; prevención: orientación de las filas y exposición, sombra mediante la gestión de la vegetación, riego antes de una ola de calor, protectores solares y mallas de sombreo; incendios más frecuentes con el cambio climático, cerca de bosques y pastos, cubiertas vegetales y acolchados como combustible; humo desde el envero: compuestos absorbidos por los hollejos, ligados a azúcares como precursores sin olor; notas ahumadas o plásticas que aparecen con la fermentación y aumentan con el envejecimiento; análisis y microvinificaciones antes de vendimiar; vendimia a mano, prensado suave o de racimo entero, fermentación más fresca, maceración corta; flash détente y ósmosis inversa ayudan pero no eliminan el defecto"],
        ["Un acino traspira molto meno di una foglia e, con caldo prolungato e sole diretto, può scaldarsi fino a scottarsi, soprattutto se la vite è già in stress idrico. Ne derivano cicatrici, imbrunimento, sapore amaro e maggior rischio di marciume: gli acini scottati vanno eliminati con la cernita, e la resa cala. Si previene già nel progetto del vigneto, con orientamento ed esposizione dei filari che evitino il sole più intenso del pomeriggio; poi con una gestione della chioma che ombreggi in parte i grappoli, con un'irrigazione supplementare prima di un'ondata di calore, dove permessa, e con prodotti protettivi o reti ombreggianti. Gli incendi, più frequenti con il clima più caldo e secco in Australia, California e Cile, sono difficili da prevenire; i vigneti vicini a boschi o pascoli sono più esposti, e cover crop e pacciame possono fare da combustibile, mentre il suolo lavorato no. Il danno maggiore per la qualità è il fumo, soprattutto da invaiatura in poi: i composti del fumo entrano nelle bucce e si legano agli zuccheri come precursori senza odore, che si liberano durante la fermentazione e continuano a liberarsi con l'invecchiamento, dando note affumicate o di plastica. Prima della vendemmia si fanno analisi e microvinificazioni per valutare il problema; poi si limita l'estrazione: vendemmia a mano, pressatura delicata o a grappolo intero, fermentazioni più fresche e macerazioni brevi. Flash détente e osmosi inversa possono aiutare, ma non eliminano del tutto il difetto.",
         "Une baie transpire bien moins qu'une feuille et, par chaleur prolongée et soleil direct, elle peut chauffer jusqu'à brûler, surtout si la vigne est déjà en stress hydrique. Il en résulte cicatrices, brunissement, goût amer et risque accru de pourriture : les baies brûlées doivent être éliminées au tri, et le rendement baisse. On prévient dès la conception du vignoble, avec une orientation et une exposition des rangs qui évitent le soleil le plus intense de l'après-midi ; puis par une conduite du feuillage qui ombrage en partie les grappes, par une irrigation d'appoint avant une canicule, là où elle est permise, et par des produits protecteurs ou des filets d'ombrage. Les incendies, plus fréquents avec un climat plus chaud et sec en Australie, en Californie et au Chili, sont difficiles à prévenir ; les vignes proches de bois ou de pâturages sont plus exposées, et couverts végétaux et paillis peuvent servir de combustible, contrairement au sol travaillé. Le plus grand dommage pour la qualité est la fumée, surtout à partir de la véraison : ses composés pénètrent dans les pellicules et se lient aux sucres en précurseurs inodores, qui se libèrent pendant la fermentation et continuent de se libérer au vieillissement, donnant des notes fumées ou de plastique. Avant la vendange, analyses et microvinifications permettent d'évaluer le problème ; ensuite on limite l'extraction : vendange manuelle, pressurage doux ou en grappes entières, fermentations plus fraîches et macérations courtes. Flash détente et osmose inverse peuvent aider, mais n'éliminent pas totalement le défaut.",
         "A berry transpires far less than a leaf and, in prolonged heat and direct sun, it can overheat until it burns, especially if the vine is already water-stressed. The result is scarring, browning, bitterness and a higher risk of rot: sunburnt berries must be removed by sorting, which lowers yield. Prevention starts with vineyard design, choosing row orientation and aspect that avoid the most intense afternoon sun; then canopy management that partly shades the bunches, extra irrigation before a heatwave where allowed, and protective sprays or shade cloth. Fires, more frequent as the climate becomes hotter and drier in Australia, California and Chile, are hard to prevent; vineyards next to woodland or pasture are more exposed, and cover crops and mulch can act as fuel, whereas cultivated soil does not. The greatest threat to quality is smoke, especially from véraison onwards: smoke compounds enter the skins and bind to sugars as odourless precursors, which are released during fermentation and continue to be released with ageing, giving smoky or plastic notes. Before harvest, analysis and micro-vinifications show the extent of the problem; then extraction is limited: hand picking, gentle or whole bunch pressing, cooler fermentation and short maceration. Flash détente and reverse osmosis can help, but do not remove the taint entirely.",
         "Una baya transpira mucho menos que una hoja y, con calor prolongado y sol directo, puede calentarse hasta quemarse, sobre todo si la cepa ya sufre estrés hídrico. El resultado son cicatrices, pardeamiento, sabor amargo y mayor riesgo de podredumbre: las bayas quemadas deben eliminarse en la selección, y el rendimiento baja. Se previene desde el diseño del viñedo, con una orientación y exposición de las filas que eviten el sol más intenso de la tarde; luego con una gestión de la vegetación que sombree en parte los racimos, con riego adicional antes de una ola de calor, donde esté permitido, y con productos protectores o mallas de sombreo. Los incendios, más frecuentes con un clima más cálido y seco en Australia, California y Chile, son difíciles de prevenir; los viñedos junto a bosques o pastos están más expuestos, y las cubiertas vegetales y los acolchados pueden servir de combustible, a diferencia del suelo labrado. El mayor daño para la calidad es el humo, sobre todo desde el envero: sus compuestos entran en los hollejos y se ligan a azúcares como precursores sin olor, que se liberan durante la fermentación y siguen liberándose con el envejecimiento, dando notas ahumadas o plásticas. Antes de vendimiar, análisis y microvinificaciones permiten valorar el problema; después se limita la extracción: vendimia a mano, prensado suave o de racimo entero, fermentaciones más frescas y maceraciones cortas. El flash détente y la ósmosis inversa pueden ayudar, pero no eliminan del todo el defecto."])]),
    Q("d1b", ["Convenzionale, sostenibile, biologico, biodinamico, di precisione: cinque approcci al vigneto.", "Conventionnel, durable, biologique, biodynamique, de précision : cinq approches du vignoble.", "Conventional, sustainable, organic, biodynamic, precision: five approaches to the vineyard.", "Convencional, sostenible, ecológico, biodinámico, de precisión: cinco enfoques del viñedo."], [
      P(["Descrivi i principi di ciascun approccio e valutane vantaggi, limiti e costi.", "Décrivez les principes de chaque approche et évaluez-en avantages, limites et coûts.", "Describe the principles of each approach and evaluate its advantages, limits and costs.", "Describe los principios de cada enfoque y valora sus ventajas, límites y costes."], 15,
        ["convenzionale: monocoltura intensiva, meccanizzazione, prodotti chimici, irrigazione, cloni produttivi; vantaggi: rese alte, meno manodopera; limiti: più malattie, suolo impoverito, residui in falda e aria, rischi per i lavoratori; sostenibile: ambiente, società ed economia, biodiversità, meno chimica ed energia; lotta integrata: monitoraggio, soglie economiche di intervento, prevenzione, chimica solo se serve; programmi regionali come LODI RULES o Sustainable Winegrowing NZ; limiti: termine non protetto, standard a volte troppo bassi; biologico: niente concimi, erbicidi e pesticidi di sintesi, compost, cover crop, concimi naturali, confusione sessuale; certificazione con periodo di conversione, standard IFOAM; limiti: rese più basse negli anni difficili, rame che si accumula, più manodopera e costi di certificazione; biodinamico: Steiner e Thun, fattoria come organismo, calendario lunare; preparati 500 e 501 e compost con preparati 502–507, Demeter, costi poco superiori al biologico, effetti scientifici non dimostrati; precisione: sensori remoti o prossimali, GPS e GIS, mappe di vigore e suolo; interventi a dose variabile per parcella o filare, qualità e rese migliori, meno trattamenti; limiti: investimento in sensori, software e personale, adatta a grandi aziende o tenute di pregio",
         "conventionnelle : monoculture intensive, mécanisation, chimie, irrigation, clones productifs ; avantages : rendements élevés, moins de main-d'œuvre ; limites : plus de maladies, sol appauvri, résidus dans les nappes et l'air, risques pour les travailleurs ; durable : environnement, social et économie, biodiversité, moins de chimie et d'énergie ; lutte raisonnée : surveillance, seuils économiques d'intervention, prévention, chimie seulement si nécessaire ; programmes régionaux comme LODI RULES ou Sustainable Winegrowing NZ ; limites : terme non protégé, normes parfois trop basses ; biologique : ni engrais, ni herbicides, ni pesticides de synthèse, compost, couverts végétaux, engrais naturels, confusion sexuelle ; certification avec période de conversion, normes IFOAM ; limites : rendements plus bas les années difficiles, cuivre qui s'accumule, plus de main-d'œuvre et coûts de certification ; biodynamique : Steiner et Thun, ferme comme organisme, calendrier lunaire ; préparations 500 et 501 et compost avec préparations 502–507, Demeter, coûts à peine supérieurs au bio, effets scientifiques non démontrés ; précision : capteurs embarqués ou aériens, GPS et SIG, cartes de vigueur et de sol ; interventions à dose variable par parcelle ou rang, qualité et rendements meilleurs, moins de traitements ; limites : investissement en capteurs, logiciels et personnel, adaptée aux grands domaines ou aux propriétés prestigieuses",
         "conventional: intensive monoculture, mechanisation, chemicals, irrigation, productive clones; advantages: high yields, less labour; limits: more disease, depleted soil, residues in groundwater and air, risks to workers; sustainable: environment, society and economy, biodiversity, fewer chemicals and less energy; integrated pest management: monitoring, economic thresholds for action, prevention, chemicals only when needed; regional schemes such as LODI RULES or Sustainable Winegrowing NZ; limits: unprotected term, standards sometimes too low; organic: no synthetic fertilisers, herbicides or pesticides, compost, cover crops, natural fertilisers, mating disruption; certification with a conversion period, IFOAM standards; limits: lower yields in difficult years, copper build-up, more labour and certification costs; biodynamic: Steiner and Thun, farm as an organism, lunar calendar; preparations 500 and 501 and compost with preparations 502–507, Demeter, costs little above organic, scientific effects unproven; precision: remote or proximal sensors, GPS and GIS, maps of vigour and soil; variable-rate interventions by block or row, better quality and yield, fewer treatments; limits: investment in sensors, software and staff, suited to large operations or high-value estates",
         "convencional: monocultivo intensivo, mecanización, productos químicos, riego, clones productivos; ventajas: rendimientos altos, menos mano de obra; límites: más enfermedades, suelo empobrecido, residuos en acuíferos y aire, riesgos para los trabajadores; sostenible: medio ambiente, sociedad y economía, biodiversidad, menos química y energía; lucha integrada: seguimiento, umbrales económicos de intervención, prevención, química solo cuando hace falta; programas regionales como LODI RULES o Sustainable Winegrowing NZ; límites: término no protegido, normas a veces demasiado bajas; ecológico: sin fertilizantes, herbicidas ni pesticidas de síntesis, compost, cubiertas vegetales, abonos naturales, confusión sexual; certificación con periodo de conversión, normas IFOAM; límites: rendimientos más bajos en años difíciles, cobre que se acumula, más mano de obra y costes de certificación; biodinámico: Steiner y Thun, la finca como organismo, calendario lunar; preparados 500 y 501 y compost con preparados 502–507, Demeter, costes poco superiores al ecológico, efectos científicos no demostrados; precisión: sensores remotos o próximos, GPS y SIG, mapas de vigor y suelo; intervenciones de dosis variable por parcela o fila, mejor calidad y rendimiento, menos tratamientos; límites: inversión en sensores, software y personal, adecuada para grandes explotaciones o fincas de prestigio"],
        ["La viticoltura convenzionale, affermatasi nella seconda metà del Novecento, è una frutticoltura intensiva: monocoltura, meccanizzazione, concimi e pesticidi di sintesi, irrigazione e cloni produttivi. Alza le rese e riduce il lavoro, ma una monocoltura è più vulnerabile a malattie e parassiti, impoverisce il suolo e lascia residui in falda e nell'aria, con rischi per lavoratori e ambiente. La viticoltura sostenibile considera ambiente, società ed economia: biodiversità, gestione dei rifiuti, meno chimica ed energia. Il suo strumento chiave è la lotta integrata (lutte raisonnée): monitorare parassiti e meteo, fissare soglie economiche oltre le quali intervenire, prevenire, e usare la chimica solo quando serve e al momento più efficace. Esistono programmi regionali come LODI RULES o Sustainable Winegrowing New Zealand; il risparmio di trattamenti incentiva l'adesione, ma il termine non è protetto e gli standard possono essere bassi. La viticoltura biologica rinuncia a concimi, erbicidi e pesticidi di sintesi; punta su compost, cover crop e sovescio, concimi naturali, siepi e biodiversità, confusione sessuale con feromoni. Serve una certificazione, dopo un periodo di conversione, secondo standard compatibili con l'IFOAM. Migliora la salute del suolo e della vite, ma può ridurre le rese negli anni piovosi, fa affidamento sul rame che si accumula nel suolo e richiede più manodopera. La biodinamica, da Rudolf Steiner e Maria Thun, aggiunge una visione cosmologica: la fattoria come organismo, lavori secondo il calendario lunare, preparati come il 500 (cornoletame) e il 501 (cornosilice) e compost attivato con i preparati 502–507; la certificazione più diffusa è Demeter, i costi sono poco superiori al biologico e la ricerca non ne ha dimostrato effetti specifici. La viticoltura di precisione usa dati raccolti da sensori su aerei o trattori, con GPS e GIS, per mappare suolo e vigore e intervenire a dose variabile parcella per parcella, migliorando qualità e rese e riducendo i trattamenti; richiede però sensori, software e personale qualificato, quindi conviene a grandi aziende o a tenute di alto valore, e spesso si combina con gli approcci sostenibile o biologico.",
         "La viticulture conventionnelle, qui s'est imposée dans la seconde moitié du XXe siècle, est une arboriculture intensive : monoculture, mécanisation, engrais et pesticides de synthèse, irrigation et clones productifs. Elle augmente les rendements et réduit le travail, mais une monoculture est plus vulnérable aux maladies et ravageurs, appauvrit le sol et laisse des résidus dans les nappes et l'air, avec des risques pour les travailleurs et l'environnement. La viticulture durable prend en compte environnement, social et économie : biodiversité, gestion des déchets, moins de chimie et d'énergie. Son outil clé est la lutte raisonnée : surveiller ravageurs et météo, fixer des seuils économiques au-delà desquels intervenir, prévenir, et n'utiliser la chimie que si nécessaire et au moment le plus efficace. Il existe des programmes régionaux comme LODI RULES ou Sustainable Winegrowing New Zealand ; l'économie de traitements incite à l'adhésion, mais le terme n'est pas protégé et les normes peuvent être basses. La viticulture biologique renonce aux engrais, herbicides et pesticides de synthèse ; elle mise sur le compost, les couverts végétaux et l'engrais vert, les engrais naturels, les haies et la biodiversité, la confusion sexuelle par phéromones. Il faut une certification, après une période de conversion, selon des normes compatibles avec l'IFOAM. Elle améliore la santé du sol et de la vigne, mais peut réduire les rendements les années pluvieuses, dépend du cuivre qui s'accumule dans le sol et demande plus de main-d'œuvre. La biodynamie, issue de Rudolf Steiner et Maria Thun, ajoute une vision cosmologique : la ferme comme organisme, des travaux selon le calendrier lunaire, des préparations comme la 500 (bouse de corne) et la 501 (silice de corne) et un compost activé par les préparations 502–507 ; la certification la plus courante est Demeter, les coûts sont à peine supérieurs au bio et la recherche n'a pas démontré d'effets spécifiques. La viticulture de précision utilise des données recueillies par des capteurs aériens ou embarqués, avec GPS et SIG, pour cartographier sol et vigueur et intervenir à dose variable parcelle par parcelle, améliorant qualité et rendements tout en réduisant les traitements ; elle exige cependant capteurs, logiciels et personnel qualifié, et convient donc aux grandes exploitations ou aux propriétés de grande valeur, souvent en complément de la viticulture durable ou biologique.",
         "Conventional viticulture, which took hold in the second half of the twentieth century, is intensive fruit farming: monoculture, mechanisation, synthetic fertilisers and pesticides, irrigation and productive clones. It raises yields and cuts labour, but a monoculture is more vulnerable to disease and pests, depletes the soil and leaves residues in groundwater and the air, with risks for workers and the environment. Sustainable viticulture considers environment, society and economy: biodiversity, waste management, fewer chemicals and less energy. Its key tool is integrated pest management (lutte raisonnée): monitoring pests and weather, setting economic thresholds above which action is taken, prevention, and using chemicals only when needed and at the most effective time. Regional schemes exist, such as LODI RULES or Sustainable Winegrowing New Zealand; savings on treatments encourage uptake, but the term is not protected and standards can be low. Organic viticulture rejects synthetic fertilisers, herbicides and pesticides; it relies on compost, cover crops and green manure, natural fertilisers, hedges and biodiversity, and pheromone mating disruption. Certification is needed, after a conversion period, to standards compatible with IFOAM. It improves soil and vine health, but can reduce yields in wet years, relies on copper that builds up in the soil and needs more labour. Biodynamics, from Rudolf Steiner and Maria Thun, adds a cosmological view: the farm as an organism, tasks timed by the lunar calendar, preparations such as 500 (horn manure) and 501 (horn silica) and compost activated with preparations 502–507; the main certifier is Demeter, costs are little above organic and research has not shown specific effects. Precision viticulture uses data from sensors on aircraft or tractors, with GPS and GIS, to map soil and vigour and apply variable-rate interventions block by block, improving quality and yield while reducing treatments; but it needs sensors, software and skilled staff, so it suits large operations or high-value estates, and is often combined with sustainable or organic approaches.",
         "La viticultura convencional, que se impuso en la segunda mitad del siglo XX, es una fruticultura intensiva: monocultivo, mecanización, fertilizantes y pesticidas de síntesis, riego y clones productivos. Eleva los rendimientos y reduce el trabajo, pero un monocultivo es más vulnerable a enfermedades y plagas, empobrece el suelo y deja residuos en acuíferos y aire, con riesgos para trabajadores y medio ambiente. La viticultura sostenible tiene en cuenta medio ambiente, sociedad y economía: biodiversidad, gestión de residuos, menos química y energía. Su herramienta clave es la lucha integrada (lutte raisonnée): vigilar plagas y meteorología, fijar umbrales económicos a partir de los cuales intervenir, prevenir y usar la química solo cuando hace falta y en el momento más eficaz. Existen programas regionales como LODI RULES o Sustainable Winegrowing New Zealand; el ahorro en tratamientos incentiva la adhesión, pero el término no está protegido y las normas pueden ser bajas. La viticultura ecológica renuncia a fertilizantes, herbicidas y pesticidas de síntesis; apuesta por el compost, las cubiertas vegetales y el abono verde, los abonos naturales, los setos y la biodiversidad, y la confusión sexual con feromonas. Exige una certificación, tras un periodo de conversión, según normas compatibles con IFOAM. Mejora la salud del suelo y de la cepa, pero puede reducir los rendimientos en años lluviosos, depende del cobre, que se acumula en el suelo, y requiere más mano de obra. La biodinámica, de Rudolf Steiner y Maria Thun, añade una visión cosmológica: la finca como organismo, labores según el calendario lunar, preparados como el 500 (estiércol en cuerno) y el 501 (sílice en cuerno) y compost activado con los preparados 502–507; la certificación más extendida es Demeter, los costes son poco superiores al ecológico y la investigación no ha demostrado efectos específicos. La viticultura de precisión usa datos de sensores en aviones o tractores, con GPS y SIG, para cartografiar suelo y vigor e intervenir con dosis variable parcela a parcela, mejorando calidad y rendimiento y reduciendo tratamientos; exige sin embargo sensores, software y personal cualificado, por lo que conviene a grandes explotaciones o fincas de alto valor, y a menudo se combina con los enfoques sostenible o ecológico."])]),
    Q("d1b", ["Talee, cloni, incroci e innesti: le scelte sul materiale vegetale.", "Boutures, clones, croisements et greffes : les choix de matériel végétal.", "Cuttings, clones, crossings and grafts: choices of planting material.", "Esquejes, clones, cruces e injertos: las decisiones sobre el material vegetal."], [
      P(["Spiega come si propaga la vite e confronta selezione clonale e selezione massale, incroci e ibridi.", "Expliquez comment la vigne se multiplie et comparez sélection clonale et sélection massale, croisements et hybrides.", "Explain how vines are propagated and compare clonal and mass selection, crossings and hybrids.", "Explica cómo se propaga la vid y compara selección clonal y masal, cruces e híbridos."], 8,
        ["talea: la tecnica più comune, molte piante insieme, permette l'innesto e i trattamenti in vivaio; propaggine: riempie le fallanze, ma su piede franco, senza protezione dalla fillossera; entrambe danno piante geneticamente identiche, non si usano i semi; mutazioni casuali: cloni con caratteristiche diverse; selezione clonale: piante favorevoli moltiplicate, per esempio Pinot Noir 115 per rossi di qualità e 521 per spumanti; cloni da vivaio testati contro i virus, ma uniformità e meno complessità, si piantano più cloni; selezione massale: talee dalle migliori viti della propria vigna dopo anni di osservazione; più diversità e materiale unico, ma costosa e rischio di diffondere virus; incrocio tra due vinifera, per esempio Pinotage, Müller-Thurgau; ibrido tra specie diverse, per esempio Vidal, resistenza a malattie e freddo, usato come portinnesto; registrazione nel catalogo OIV, i consumatori frenano le novità",
         "bouture : la technique la plus courante, beaucoup de plants à la fois, permet le greffage et les traitements en pépinière ; marcottage : comble les manquants, mais franc de pied, sans protection contre le phylloxéra ; les deux donnent des plants génétiquement identiques, on n'utilise pas les pépins ; mutations aléatoires : clones aux caractères différents ; sélection clonale : plants favorables multipliés, par exemple Pinot Noir 115 pour les rouges de qualité et 521 pour les effervescents ; clones de pépinière testés contre les virus, mais uniformité et moins de complexité, on plante plusieurs clones ; sélection massale : boutures des meilleurs ceps de sa vigne après des années d'observation ; plus de diversité et matériel unique, mais coûteuse et risque de propager des virus ; croisement entre deux vinifera, par exemple Pinotage, Müller-Thurgau ; hybride entre espèces différentes, par exemple Vidal, résistance aux maladies et au froid, utilisé comme porte-greffe ; inscription au catalogue de l'OIV, les consommateurs freinent les nouveautés",
         "cutting: the commonest technique, many plants at once, allows grafting and nursery treatments; layering: fills gaps, but on own roots, with no protection against phylloxera; both give genetically identical plants, seeds are not used; random mutations: clones with different characteristics; clonal selection: favourable plants multiplied, for example Pinot Noir 115 for quality reds and 521 for sparkling; nursery clones tested free of virus, but uniformity and less complexity, several clones planted; mass selection: cuttings from the best vines of one's own vineyard after years of observation; more diversity and unique material, but costly and a risk of spreading virus; crossing between two vinifera, for example Pinotage, Müller-Thurgau; hybrid between different species, for example Vidal, resistance to disease and cold, used as rootstocks; registration in the OIV catalogue, consumers slow adoption of new varieties",
         "esqueje: la técnica más común, muchas plantas a la vez, permite el injerto y los tratamientos en vivero; acodo: rellena las marras, pero sobre pie franco, sin protección contra la filoxera; ambos dan plantas genéticamente idénticas, no se usan semillas; mutaciones aleatorias: clones con características distintas; selección clonal: plantas favorables multiplicadas, por ejemplo Pinot Noir 115 para tintos de calidad y 521 para espumosos; clones de vivero libres de virus, pero uniformidad y menos complejidad, se plantan varios clones; selección masal: esquejes de las mejores cepas del propio viñedo tras años de observación; más diversidad y material único, pero costosa y riesgo de propagar virus; cruce entre dos vinifera, por ejemplo Pinotage, Müller-Thurgau; híbrido entre especies distintas, por ejemplo Vidal, resistencia a enfermedades y frío, usado como portainjerto; registro en el catálogo de la OIV, los consumidores frenan las novedades"],
        ["Oggi la vite si propaga per talea o per propaggine. La talea, un tratto di tralcio che radica, è di gran lunga la tecnica più diffusa: permette di produrre molte piante insieme, di innestarle su un portinnesto e di trattarle in vivaio. La propaggine riempie le fallanze piegando e interrando un tralcio di una vite vicina, che radica e poi viene separato; la nuova pianta è però su piede franco, senza protezione dalla fillossera né i vantaggi di un portinnesto. Entrambe danno piante geneticamente identiche alla madre; i semi non si usano perché darebbero piante diverse. Durante la crescita, però, avvengono mutazioni casuali: alcune viti hanno acini più piccoli, bucce più spesse o più resistenza. La selezione clonale moltiplica le viti con caratteri favorevoli: il Pinot Noir 115 dà poche uve piccole, adatte ai rossi di qualità, il 521 rese più alte di acini più grandi, adatte agli spumanti. I cloni comprati in vivaio sono controllati contro i virus, ma l'offerta limitata rende i vigneti uniformi, con meno complessità e più vulnerabilità alle malattie, per cui si piantano più cloni. La selezione massale, praticata prima dei cloni e oggi tornata in voga, prende talee dalle migliori viti della propria vigna dopo anni di osservazione: aumenta la diversità e dà materiale unico, utile anche nel marketing, ma è costosa e può diffondere virus. Le nuove varietà nascono da semi dopo l'impollinazione incrociata: tra due vinifera si ottiene un incrocio (il Pinotage da Pinot Noir e Cinsaut, il Müller-Thurgau, produttivo ma lontano dal Riesling), tra specie diverse un ibrido (il Vidal). Gli ibridi uniscono resistenze a malattie, parassiti e freddo e la qualità della vinifera, con risultati alterni; molti servono come portinnesti. Una nuova varietà va registrata nel catalogo dell'OIV, e le richieste dei consumatori ne frenano la diffusione.",
         "Aujourd'hui la vigne se multiplie par bouture ou par marcottage. La bouture, un fragment de sarment qui s'enracine, est de loin la technique la plus répandue : elle permet de produire beaucoup de plants à la fois, de les greffer sur un porte-greffe et de les traiter en pépinière. Le marcottage comble les manquants en courbant et en enterrant un sarment d'un cep voisin, qui s'enracine puis est sevré ; le nouveau plant est cependant franc de pied, sans protection contre le phylloxéra ni les avantages d'un porte-greffe. Les deux donnent des plants génétiquement identiques à la mère ; on n'utilise pas les pépins, qui donneraient des plantes différentes. Pendant la croissance surviennent pourtant des mutations aléatoires : certains ceps ont des baies plus petites, des pellicules plus épaisses ou plus de résistance. La sélection clonale multiplie les ceps aux caractères favorables : le Pinot Noir 115 donne peu de petites baies, adaptées aux rouges de qualité, le 521 des rendements plus élevés de baies plus grosses, adaptées aux effervescents. Les clones achetés en pépinière sont contrôlés contre les virus, mais l'offre limitée uniformise les vignobles, avec moins de complexité et plus de vulnérabilité aux maladies, d'où la plantation de plusieurs clones. La sélection massale, pratiquée avant les clones et revenue en vogue, prélève des boutures sur les meilleurs ceps de sa propre vigne après des années d'observation : elle accroît la diversité et donne un matériel unique, utile aussi en marketing, mais elle coûte cher et peut propager des virus. Les nouveaux cépages naissent de pépins après pollinisation croisée : entre deux vinifera on obtient un croisement (le Pinotage, de Pinot Noir et Cinsaut ; le Müller-Thurgau, productif mais loin du Riesling), entre espèces différentes un hybride (le Vidal). Les hybrides associent résistances aux maladies, aux ravageurs et au froid et qualité de la vinifera, avec des résultats inégaux ; beaucoup servent de porte-greffes. Un nouveau cépage doit être inscrit au catalogue de l'OIV, et les attentes des consommateurs freinent sa diffusion.",
         "Today vines are propagated by cuttings or layering. A cutting, a section of shoot that takes root, is by far the commonest technique: many plants can be produced at once, grafted onto a rootstock and treated in the nursery. Layering fills gaps by bending down and burying a cane from a neighbouring vine, which roots and is then cut free; the new vine, however, is on its own roots, without protection against phylloxera or the advantages of a rootstock. Both give plants genetically identical to the parent; seeds are not used, as they would give different plants. During growth, however, random mutations occur: some vines have smaller berries, thicker skins or more resistance. Clonal selection multiplies vines with favourable traits: Pinot Noir 115 gives low yields of small berries, suited to quality reds, while 521 gives higher yields of bigger berries, suited to sparkling wine. Nursery clones are tested free of virus, but limited supply makes vineyards uniform, with less complexity and more vulnerability to disease, so growers plant several clones. Mass selection, practised before clones and now regaining popularity, takes cuttings from the best vines in one's own vineyard after years of monitoring: it increases diversity and gives unique material, useful in marketing too, but it is costly and can spread virus. New varieties come from seeds after cross-pollination: two vinifera parents give a crossing (Pinotage from Pinot Noir and Cinsaut; Müller-Thurgau, productive but far from Riesling in quality), different species give a hybrid (Vidal). Hybrids combine resistance to disease, pests and cold with vinifera quality, with mixed results; many are used as rootstocks. A new variety must be registered in the OIV catalogue, and consumer expectations slow its uptake.",
         "Hoy la vid se propaga por esqueje o por acodo. El esqueje, un trozo de brote que enraíza, es con mucho la técnica más extendida: permite producir muchas plantas a la vez, injertarlas sobre un portainjerto y tratarlas en el vivero. El acodo rellena marras doblando y enterrando una vara de una cepa vecina, que enraíza y luego se separa; la nueva planta queda sin embargo sobre pie franco, sin protección frente a la filoxera ni las ventajas de un portainjerto. Ambos dan plantas genéticamente idénticas a la madre; no se usan semillas, que darían plantas distintas. Durante el crecimiento, sin embargo, se producen mutaciones aleatorias: algunas cepas tienen bayas más pequeñas, hollejos más gruesos o más resistencia. La selección clonal multiplica las cepas con rasgos favorables: el Pinot Noir 115 da pocas bayas pequeñas, adecuadas para tintos de calidad, y el 521 rendimientos más altos de bayas más grandes, adecuadas para espumosos. Los clones de vivero están controlados frente a virus, pero la oferta limitada uniformiza los viñedos, con menos complejidad y más vulnerabilidad a enfermedades, por lo que se plantan varios clones. La selección masal, practicada antes de los clones y hoy de nuevo en auge, toma esquejes de las mejores cepas del propio viñedo tras años de observación: aumenta la diversidad y da un material único, útil también en marketing, pero es costosa y puede propagar virus. Las nuevas variedades nacen de semillas tras la polinización cruzada: dos vinifera dan un cruce (el Pinotage, de Pinot Noir y Cinsault; el Müller-Thurgau, productivo pero lejos del Riesling), especies distintas un híbrido (el Vidal). Los híbridos combinan resistencia a enfermedades, plagas y frío con la calidad de la vinifera, con resultados desiguales; muchos se usan como portainjertos. Una nueva variedad debe registrarse en el catálogo de la OIV, y las expectativas de los consumidores frenan su difusión."]),
      P(["Spiega come la scelta del portinnesto, il sovrainnesto e l'età della vite influenzano resa, qualità e costi.", "Expliquez comment le choix du porte-greffe, le surgreffage et l'âge de la vigne influencent rendement, qualité et coûts.", "Explain how the choice of rootstock, head grafting and vine age influence yield, quality and costs.", "Explica cómo la elección del portainjerto, el sobreinjerto y la edad de la cepa influyen en el rendimiento, la calidad y los costes."], 7,
        ["portinnesto anzitutto contro la fillossera, spesso ibrido di due specie; alcuni tollerano i nematodi, per esempio Ramsey e Dog Ridge; rupestris × berlandieri come 110R e 140R resistono alla siccità, riparia ai suoli umidi, 1103P alla salinità; 41B tollera il calcare, 99R e 110R i suoli acidi; bassa vigoria (riparia, 420A, 3309C) anticipa la maturazione, alta vigoria (140R) aumenta la crescita su suoli poveri o per spumanti; sovrainnesto: nuova varietà sul tronco esistente, frutto in meno tempo, segue le mode, ma portinnesto scelto per l'altra varietà; viti giovani: rese basse fino a circa 5 anni, infiorescenze tolte nei primi anni; massima produzione tra circa 10 e 40 anni, poi la vigoria cala; viti vecchie: più concentrazione ed equilibrio, riserve di carboidrati, redditizie solo con prezzi alti; «vecchie vigne» non è un termine regolamentato",
         "porte-greffe d'abord contre le phylloxéra, souvent hybride de deux espèces ; certains tolèrent les nématodes, par exemple Ramsey et Dog Ridge ; rupestris × berlandieri comme 110R et 140R résistent à la sécheresse, riparia aux sols humides, 1103P à la salinité ; 41B tolère le calcaire, 99R et 110R les sols acides ; faible vigueur (riparia, 420A, 3309C) avance la maturité, forte vigueur (140R) dope la croissance sur sols pauvres ou pour les effervescents ; surgreffage : nouveau cépage sur le tronc existant, récolte plus rapide, suit les modes, mais porte-greffe choisi pour l'ancien cépage ; jeunes vignes : rendements faibles jusqu'à environ 5 ans, inflorescences supprimées les premières années ; production maximale entre environ 10 et 40 ans, puis la vigueur baisse ; vieilles vignes : plus de concentration et d'équilibre, réserves de glucides, rentables seulement à prix élevés ; « vieilles vignes » n'est pas une mention réglementée",
         "rootstock first of all against phylloxera, often a hybrid of two species; some tolerate nematodes, for example Ramsey and Dog Ridge; rupestris × berlandieri such as 110R and 140R resist drought, riparia suits wet soils, 1103P tolerates salinity; 41B tolerates lime, 99R and 110R acid soils; low vigour (riparia, 420A, 3309C) advances ripening, high vigour (140R) boosts growth on poor soils or for sparkling; head grafting: new variety on the existing trunk, fruit sooner, follows fashion, but the rootstock was chosen for the old variety; young vines: low yields up to about 5 years, inflorescences removed in the first years; maximum yields from about 10 to 40 years, then vigour declines; old vines: more concentration and balance, carbohydrate reserves, profitable only at high prices; 'old vines' is not a regulated term",
         "portainjerto ante todo contra la filoxera, a menudo híbrido de dos especies; algunos toleran los nematodos, por ejemplo Ramsey y Dog Ridge; rupestris × berlandieri como 110R y 140R resisten la sequía, riparia los suelos húmedos, 1103P la salinidad; 41B tolera la caliza, 99R y 110R los suelos ácidos; poco vigor (riparia, 420A, 3309C) adelanta la maduración, mucho vigor (140R) impulsa el crecimiento en suelos pobres o para espumosos; sobreinjerto: nueva variedad sobre el tronco existente, fruto antes, sigue las modas, pero el portainjerto se eligió para la variedad anterior; cepas jóvenes: rendimientos bajos hasta unos 5 años, se eliminan las inflorescencias los primeros años; producción máxima entre unos 10 y 40 años, luego baja el vigor; cepas viejas: más concentración y equilibrio, reservas de carbohidratos, rentables solo con precios altos; «viñas viejas» no es un término regulado"],
        ["Quasi tutte le viti sono innestate, anzitutto per resistere alla fillossera, ma i portinnesti, spesso ibridi di due specie, offrono altre scelte. Alcuni tollerano i nematodi galligeni, come Ramsey e Dog Ridge. Gli ibridi di V. rupestris e V. berlandieri, come 110R e 140R, radicano in profondità e resistono alla siccità; quelli da V. riparia, come Riparia Gloire, tollerano i suoli impregnati d'acqua; l'1103P resiste alla salinità. Il 41B tollera i suoli calcarei, 99R e 110R quelli acidi. Infine la vigoria: portinnesti deboli (420A, 3309C) anticipano la maturazione nei climi freschi, quelli vigorosi (140R) sostengono la crescita su suoli poveri e asciutti o servono a rese alte di uve fresche e acide per spumanti. Il sovrainnesto consiste nel tagliare la vite al tronco e innestarvi una nuova varietà: con un apparato radicale già sviluppato, la vite produce uva da vino molto prima di un nuovo impianto, per seguire le mode del mercato, ma il portinnesto era stato scelto per la varietà precedente. L'età conta. Nei primi due o tre anni si tolgono le infiorescenze perché la vite cresca; fino a circa cinque anni le rese restano basse; tra 10 e 40 anni circa la produzione è massima, poi la vigoria e le rese calano. Le viti vecchie sono spesso associate a vini più concentrati ed equilibrati, forse per rese più basse, riserve di carboidrati nel legno vecchio e siti migliori, ma restano redditizie solo dove i prezzi sono alti, come in Borgogna o in Eden Valley; altrove si espiantano. «Vecchie vigne» non è un termine regolamentato, anche se esistono associazioni di tutela come la Barossa Old Vine Charter.",
         "Presque toutes les vignes sont greffées, d'abord pour résister au phylloxéra, mais les porte-greffes, souvent hybrides de deux espèces, offrent d'autres choix. Certains tolèrent les nématodes à galles, comme Ramsey et Dog Ridge. Les hybrides de V. rupestris et V. berlandieri, comme 110R et 140R, s'enracinent profondément et résistent à la sécheresse ; ceux issus de V. riparia, comme Riparia Gloire, tolèrent les sols gorgés d'eau ; le 1103P résiste à la salinité. Le 41B tolère les sols calcaires, 99R et 110R les sols acides. Reste la vigueur : des porte-greffes faibles (420A, 3309C) avancent la maturité en climat frais, des vigoureux (140R) soutiennent la croissance sur sols pauvres et secs ou servent à des rendements élevés de raisins frais et acides pour les effervescents. Le surgreffage consiste à couper la vigne au tronc et à y greffer un nouveau cépage : avec un système racinaire déjà installé, la vigne donne du raisin de cuve bien plus tôt qu'une nouvelle plantation, pour suivre les modes du marché, mais le porte-greffe avait été choisi pour l'ancien cépage. L'âge compte. Les deux ou trois premières années, on supprime les inflorescences pour que la vigne pousse ; jusqu'à environ cinq ans, les rendements restent faibles ; entre 10 et 40 ans environ, la production est maximale, puis vigueur et rendements baissent. Les vieilles vignes sont souvent associées à des vins plus concentrés et équilibrés, peut-être grâce à des rendements plus bas, aux réserves de glucides du vieux bois et à de meilleurs sites, mais elles ne restent rentables que là où les prix sont élevés, comme en Bourgogne ou dans l'Eden Valley ; ailleurs on les arrache. « Vieilles vignes » n'est pas une mention réglementée, même s'il existe des associations de protection comme la Barossa Old Vine Charter.",
         "Nearly all vines are grafted, first of all to resist phylloxera, but rootstocks, often hybrids of two species, offer further choices. Some tolerate root-knot nematodes, such as Ramsey and Dog Ridge. Hybrids of V. rupestris and V. berlandieri, such as 110R and 140R, root deeply and resist drought; those based on V. riparia, such as Riparia Gloire, tolerate waterlogged soils; 1103P tolerates salinity. 41B tolerates lime-rich soils, 99R and 110R acid soils. Then there is vigour: low-vigour rootstocks (420A, 3309C) advance ripening in cool climates, while vigorous ones (140R) support growth on poor, dry soils or give high yields of fresh, acidic grapes for sparkling wine. Head grafting means cutting the vine at the trunk and grafting a new variety on top: with an established root system the vine produces wine grapes much sooner than a new planting, allowing growers to follow market trends, but the rootstock was chosen for the previous variety. Age matters. In the first two or three years inflorescences are removed so that the vine can grow; up to about five years yields remain low; from about 10 to 40 years production is at its peak, then vigour and yields decline. Old vines are often linked to more concentrated, balanced wines, perhaps because of lower yields, carbohydrate reserves in old wood and better sites, but they stay profitable only where prices are high, as in Burgundy or the Eden Valley; elsewhere they are grubbed up. 'Old vines' is not a regulated term, although protective associations exist, such as the Barossa Old Vine Charter.",
         "Casi todas las vides están injertadas, ante todo para resistir la filoxera, pero los portainjertos, a menudo híbridos de dos especies, ofrecen otras opciones. Algunos toleran los nematodos formadores de agallas, como Ramsey y Dog Ridge. Los híbridos de V. rupestris y V. berlandieri, como 110R y 140R, enraízan en profundidad y resisten la sequía; los derivados de V. riparia, como Riparia Gloire, toleran los suelos encharcados; el 1103P resiste la salinidad. El 41B tolera los suelos calizos, 99R y 110R los ácidos. Queda el vigor: los portainjertos débiles (420A, 3309C) adelantan la maduración en climas frescos y los vigorosos (140R) sostienen el crecimiento en suelos pobres y secos o dan rendimientos altos de uva fresca y ácida para espumosos. El sobreinjerto consiste en cortar la cepa por el tronco e injertar una nueva variedad: con un sistema radicular ya establecido, la cepa da uva de vinificación mucho antes que una nueva plantación, lo que permite seguir las modas del mercado, pero el portainjerto se eligió para la variedad anterior. La edad cuenta. Los dos o tres primeros años se quitan las inflorescencias para que la cepa crezca; hasta unos cinco años los rendimientos son bajos; entre unos 10 y 40 años la producción es máxima, y después bajan el vigor y los rendimientos. Las cepas viejas se asocian a menudo con vinos más concentrados y equilibrados, quizá por rendimientos más bajos, reservas de carbohidratos en la madera vieja y mejores emplazamientos, pero solo siguen siendo rentables donde los precios son altos, como en Borgoña o el Eden Valley; en otros lugares se arrancan. «Viñas viejas» no es un término regulado, aunque existen asociaciones de protección como la Barossa Old Vine Charter."])]),
    Q("d1b", ["Suolo, nutrienti e acqua: ciò che la vite trova sotto terra.", "Sol, nutriments et eau : ce que la vigne trouve sous terre.", "Soil, nutrients and water: what the vine finds below ground.", "Suelo, nutrientes y agua: lo que la vid encuentra bajo tierra."], [
      P(["Spiega come il viticoltore gestisce la salute del suolo, i nutrienti e le infestanti e confronta le opzioni.", "Expliquez comment le viticulteur gère la santé du sol, les nutriments et les adventices, et comparez les options.", "Explain how the grower manages soil health, nutrients and weeds, and compare the options.", "Explica cómo el viticultor gestiona la salud del suelo, los nutrientes y las malas hierbas, y compara las opciones."], 7,
        ["suolo sano: struttura, drenaggio, ritenzione idrica, sostanza organica e humus, organismi viventi, nutrienti disponibili; analisi del suolo all'impianto e ogni anno; concimi organici, letame, compost, sovescio: economici, migliorano struttura e vita del suolo, rilascio lento, ingombranti; concimi minerali: mirati e subito disponibili, facili da trasportare, nessun beneficio per il suolo; troppo concime: vigoria eccessiva; lavorazione del suolo: niente chimica, interra concimi, ma danneggia struttura e lombrichi, costosa; erbicidi pre-emergenza, di contatto e sistemici: economici ed efficaci sotto il filare, rischi per salute e ambiente, resistenze, vietati in biologico; pascolo di animali, cover crop che competono e regolano la vigoria, pacciamatura che trattiene acqua ma costa trasportarla; suolo nudo e umido riduce il rischio di gelo, le coperture lo aumentano",
         "sol sain : structure, drainage, réserve en eau, matière organique et humus, organismes vivants, nutriments disponibles ; analyses de sol à la plantation et chaque année ; engrais organiques, fumier, compost, engrais vert : bon marché, améliorent structure et vie du sol, libération lente, encombrants ; engrais minéraux : ciblés et vite disponibles, faciles à transporter, aucun bénéfice pour le sol ; trop d'engrais : vigueur excessive ; travail du sol : sans chimie, enfouit les engrais, mais abîme la structure et les vers de terre, coûteux ; herbicides de prélevée, de contact et systémiques : bon marché et efficaces sous le rang, risques pour la santé et l'environnement, résistances, interdits en bio ; pâturage d'animaux, couverts végétaux qui concurrencent et régulent la vigueur, paillage qui retient l'eau mais coûte à transporter ; sol nu et humide réduit le risque de gel, les couverts l'augmentent",
         "healthy soil: structure, drainage, water-holding capacity, organic matter and humus, living organisms, available nutrients; soil tests at planting and every year; organic fertilisers, manure, compost, green manure: cheap, improve soil structure and life, slow release, bulky; mineral fertilisers: targeted and quickly available, easy to transport, no benefit to the soil; too much fertiliser: excess vigour; cultivation: no chemicals, incorporates fertiliser, but damages structure and earthworms, costly; pre-emergence, contact and systemic herbicides: cheap and effective under the row, risks to health and environment, resistance, banned in organic; grazing animals, cover crops that compete and regulate vigour, mulch that keeps water in but is costly to transport; bare moist soil reduces frost risk, cover increases it",
         "suelo sano: estructura, drenaje, retención de agua, materia orgánica y humus, organismos vivos, nutrientes disponibles; análisis de suelo al plantar y cada año; abonos orgánicos, estiércol, compost, abono verde: baratos, mejoran estructura y vida del suelo, liberación lenta, voluminosos; fertilizantes minerales: precisos y disponibles enseguida, fáciles de transportar, ningún beneficio para el suelo; demasiado abono: vigor excesivo; laboreo: sin química, entierra el abono, pero daña la estructura y las lombrices, caro; herbicidas de preemergencia, de contacto y sistémicos: baratos y eficaces bajo la fila, riesgos para la salud y el medio ambiente, resistencias, prohibidos en ecológico; pastoreo de animales, cubiertas vegetales que compiten y regulan el vigor, acolchado que retiene agua pero es caro de transportar; suelo desnudo y húmedo reduce el riesgo de helada, las cubiertas lo aumentan"],
        ["Un suolo sano ha una buona struttura (drenaggio, ritenzione idrica, ossigeno, resistenza all'erosione, profondità esplorabile dalle radici), abbastanza sostanza organica e humus, molti organismi viventi, come lombrichi e microbi che trasformano la sostanza organica in nutrienti assimilabili, e nutrienti disponibili in equilibrio. Il viticoltore fa analisi all'impianto e poi ogni anno per correggere struttura e livelli di nutrienti. I concimi organici (letame, compost, sovescio di cover crop) sono spesso economici, nutrono la vita del suolo e ne migliorano struttura e ritenzione, ma vanno interrati, liberano i nutrienti lentamente e sono ingombranti da trasportare. I concimi minerali sono mirati, subito disponibili e concentrati, quindi economici da trasportare, ma non giovano al suolo. In entrambi i casi un eccesso porta a vigoria eccessiva e squilibrio. Le infestanti competono per acqua e nutrienti. La lavorazione del suolo non usa chimica e interra concimi e cover crop, ma ripetuta danneggia struttura e lombrichi, costa macchine e manodopera e rimescola i semi. Gli erbicidi (pre-emergenza, di contatto, sistemici) sono economici ed efficaci sotto il filare, ma comportano rischi per operatori, consumatori e ambiente, creano resistenze, come per il glifosato in Sudafrica, e sono vietati in biologico. Il pascolo di pecore richiede viti alte o tempi fuori stagione. Le cover crop aumentano biodiversità e portanza per le macchine e possono ridurre la vigoria con la competizione, ma vanno gestite per non togliere troppa acqua; la pacciamatura sopprime le infestanti e riduce l'evaporazione, ma serve in strati spessi e costa trasportarla. Il suolo nudo e umido, infine, assorbe calore di giorno e lo restituisce di notte, riducendo il rischio di gelate.",
         "Un sol sain a une bonne structure (drainage, réserve en eau, oxygène, résistance à l'érosion, profondeur prospectable par les racines), assez de matière organique et d'humus, beaucoup d'organismes vivants, comme les vers de terre et les microbes qui transforment la matière organique en nutriments assimilables, et des nutriments disponibles en équilibre. Le viticulteur fait des analyses à la plantation puis chaque année pour corriger structure et niveaux de nutriments. Les engrais organiques (fumier, compost, engrais vert issu des couverts) sont souvent bon marché, nourrissent la vie du sol et améliorent structure et réserve en eau, mais il faut les incorporer, ils libèrent lentement les nutriments et sont encombrants à transporter. Les engrais minéraux sont ciblés, vite disponibles et concentrés, donc économiques à transporter, mais ils n'apportent rien au sol. Dans les deux cas, un excès entraîne une vigueur excessive et un déséquilibre. Les adventices concurrencent la vigne pour l'eau et les nutriments. Le travail du sol n'utilise pas de chimie et enfouit engrais et couverts, mais répété il abîme la structure et les vers de terre, coûte en machines et en main-d'œuvre et remonte les graines. Les herbicides (de prélevée, de contact, systémiques) sont bon marché et efficaces sous le rang, mais présentent des risques pour les opérateurs, les consommateurs et l'environnement, créent des résistances, comme pour le glyphosate en Afrique du Sud, et sont interdits en bio. Le pâturage de moutons exige des vignes hautes ou une période hors saison. Les couverts végétaux accroissent la biodiversité et la portance pour les machines et peuvent réduire la vigueur par concurrence, mais doivent être gérés pour ne pas prendre trop d'eau ; le paillage supprime les adventices et réduit l'évaporation, mais doit être épais et coûte à transporter. Enfin, un sol nu et humide absorbe la chaleur le jour et la restitue la nuit, réduisant le risque de gel.",
         "A healthy soil has good structure (drainage, water-holding capacity, oxygen, resistance to erosion, depth that roots can explore), enough organic matter and humus, plenty of living organisms, such as earthworms and microbes that turn organic matter into available nutrients, and a balanced supply of available nutrients. Growers test the soil at planting and then every year to correct structure and nutrient levels. Organic fertilisers (manure, compost, green manure from cover crops) are often cheap, feed soil life and improve structure and water retention, but must be incorporated, release nutrients slowly and are bulky to transport. Mineral fertilisers are targeted, quickly available and concentrated, so cheap to transport, but do nothing for the soil. In both cases excess leads to too much vigour and an unbalanced vine. Weeds compete for water and nutrients. Cultivation uses no chemicals and incorporates fertiliser and cover crops, but repeated it damages structure and earthworms, costs machinery and labour and brings up seeds. Herbicides (pre-emergence, contact, systemic) are cheap and effective under the row, but carry risks for operators, consumers and the environment, create resistance, as with glyphosate in South Africa, and are banned in organic farming. Grazing sheep requires high-trained vines or out-of-season grazing. Cover crops increase biodiversity and give a firm surface for machinery and can reduce vigour through competition, but must be managed so they do not take too much water; mulch suppresses weeds and reduces evaporation, but must be thick and is costly to transport. Finally, bare, moist soil absorbs heat by day and releases it at night, reducing frost risk.",
         "Un suelo sano tiene buena estructura (drenaje, retención de agua, oxígeno, resistencia a la erosión, profundidad explorable por las raíces), suficiente materia orgánica y humus, muchos organismos vivos, como lombrices y microbios que transforman la materia orgánica en nutrientes asimilables, y nutrientes disponibles en equilibrio. El viticultor hace análisis al plantar y después cada año para corregir estructura y niveles de nutrientes. Los abonos orgánicos (estiércol, compost, abono verde de las cubiertas) suelen ser baratos, alimentan la vida del suelo y mejoran estructura y retención de agua, pero hay que incorporarlos, liberan los nutrientes despacio y son voluminosos de transportar. Los fertilizantes minerales son precisos, disponibles enseguida y concentrados, por lo que su transporte es barato, pero no aportan nada al suelo. En ambos casos el exceso provoca vigor excesivo y desequilibrio. Las malas hierbas compiten por agua y nutrientes. El laboreo no usa química e incorpora abonos y cubiertas, pero repetido daña la estructura y las lombrices, cuesta maquinaria y mano de obra y saca semillas a la superficie. Los herbicidas (de preemergencia, de contacto, sistémicos) son baratos y eficaces bajo la fila, pero suponen riesgos para operarios, consumidores y medio ambiente, generan resistencias, como con el glifosato en Sudáfrica, y están prohibidos en ecológico. El pastoreo de ovejas exige cepas altas o hacerlo fuera de temporada. Las cubiertas vegetales aumentan la biodiversidad y dan firmeza al suelo para las máquinas y pueden reducir el vigor por competencia, pero hay que gestionarlas para que no quiten demasiada agua; el acolchado suprime las malas hierbas y reduce la evaporación, pero debe ser grueso y es caro de transportar. Por último, el suelo desnudo y húmedo absorbe calor de día y lo devuelve de noche, reduciendo el riesgo de heladas."]),
      P(["Confronta i sistemi di irrigazione e spiega come l'irrigazione in deficit controllato e l'aridocoltura influenzano resa e qualità.", "Comparez les systèmes d'irrigation et expliquez comment l'irrigation déficitaire contrôlée et la culture sèche influencent rendement et qualité.", "Compare irrigation systems and explain how regulated deficit irrigation and dry farming influence yield and quality.", "Compara los sistemas de riego y explica cómo el riego deficitario controlado y el secano influyen en el rendimiento y la calidad."], 8,
        ["irrigazione da prevedere all'impianto, alcune DOP europee la vietano o la limitano alle emergenze; acqua scarsa e regolamentata, siccità in Australia, California e Sudafrica: efficienza; goccia a goccia il sistema più diffuso: controllo per filare, fertirrigazione, meno acqua; goccia: installazione costosa, acqua pulita, gocciolatori che si intasano, inutile contro il gelo; scorrimento e solchi: economici ma inefficienti, solo in piano, comuni in Argentina con l'acqua delle Ande; aspersione a pioggia: costosa e consuma più acqua, ma protegge dal gelo; qualità dell'acqua: solidi da filtrare, salinità che disidrata la vite, peggiore con il goccia; acqua abbondante in primavera per la superficie fogliare, lieve stress tra allegagione e invaiatura; deficit controllato: stress moderato e programmato con il goccia, ferma i germogli, acini più piccoli, più colore e tannino; deficit controllato più facile in climi secchi e suoli sabbiosi, rese più basse, serve monitorare l'umidità; aridocoltura: niente irrigazione dove piove poco, rese più basse, acqua regolata con cover crop e struttura del suolo",
         "irrigation à prévoir dès la plantation, certaines AOP européennes l'interdisent ou la limitent aux urgences ; eau rare et réglementée, sécheresses en Australie, Californie et Afrique du Sud : efficacité ; goutte-à-goutte, le système le plus répandu : contrôle par rang, fertirrigation, moins d'eau ; goutte-à-goutte : installation coûteuse, eau propre, goutteurs qui se bouchent, inutile contre le gel ; submersion et rigoles : bon marché mais inefficaces, seulement sur terrain plat, courantes en Argentine grâce à l'eau des Andes ; aspersion : coûteuse et gourmande en eau, mais protège du gel ; qualité de l'eau : solides à filtrer, salinité qui déshydrate la vigne, pire avec le goutte-à-goutte ; eau abondante au printemps pour la surface foliaire, léger stress entre nouaison et véraison ; irrigation déficitaire contrôlée : stress modéré programmé au goutte-à-goutte, arrête les rameaux, baies plus petites, plus de couleur et de tanin ; plus facile en climat sec et sols sableux, rendements plus bas, suivi de l'humidité du sol nécessaire ; culture sèche : pas d'irrigation là où il pleut peu, rendements plus bas, eau régulée par couverts et structure du sol",
         "irrigation should be planned at establishment, some European PDOs ban it or allow it only in emergencies; water is scarce and regulated, droughts in Australia, California and South Africa: efficiency; drip, the commonest system: control by row, fertigation, less water; drip: costly to install, needs clean water, drippers clog, useless against frost; flood and channel: cheap but inefficient, only on flat land, common in Argentina thanks to Andean water; overhead sprinklers: costly and use more water, but give frost protection; water quality: solids to filter, salinity that dehydrates the vine, worse with drip; plentiful water in spring for leaf area, mild stress between fruit set and véraison; regulated deficit irrigation: moderate, scheduled stress with drip, stops shoots, smaller berries, more colour and tannin; RDI easier in dry climates and sandy soils, lower yields, soil moisture monitoring needed; dry farming: no irrigation where rainfall is low, lower yields, water regulated with cover crops and soil structure",
         "el riego debe preverse al plantar, algunas DOP europeas lo prohíben o lo limitan a emergencias; agua escasa y regulada, sequías en Australia, California y Sudáfrica: eficiencia; goteo, el sistema más extendido: control por fila, fertirrigación, menos agua; goteo: instalación cara, agua limpia, goteros que se obstruyen, inútil contra la helada; inundación y surcos: baratos pero ineficientes, solo en llano, comunes en Argentina gracias al agua de los Andes; aspersión: cara y gasta más agua, pero protege de la helada; calidad del agua: sólidos que filtrar, salinidad que deshidrata la cepa, peor con el goteo; agua abundante en primavera para la superficie foliar, ligero estrés entre cuajado y envero; riego deficitario controlado: estrés moderado y programado con goteo, frena los brotes, bayas más pequeñas, más color y tanino; más fácil en climas secos y suelos arenosos, rendimientos más bajos, hay que medir la humedad del suelo; secano: sin riego donde llueve poco, rendimientos más bajos, agua regulada con cubiertas y estructura del suelo"],
        ["Dove piove poco o i suoli drenano troppo, l'irrigazione va prevista già nel progetto del vigneto, perché installarla dopo è molto più complicato; alcune DOP europee la vietano o la permettono solo in emergenza. L'acqua è scarsa e regolamentata, e le siccità in Australia, California e Sudafrica spingono all'efficienza. Il goccia a goccia è di gran lunga il sistema più diffuso: tubi lungo ogni filare con gocciolatori distanti dal tronco per spingere le radici a esplorare; permette di dosare l'acqua per filare o parcella e di distribuire concimi liquidi, ma costa installarlo, richiede acqua pulita e manutenzione perché i gocciolatori si intasano, e non serve contro il gelo. Lo scorrimento e i solchi costano poco ma sprecano acqua e richiedono terreni piani: sono diffusi in Argentina, dove l'acqua delle Ande abbonda. L'aspersione a pioggia è costosa e consuma più acqua del goccia, ma protegge dalle gelate. Conta anche la qualità dell'acqua: i solidi vanno filtrati, e l'acqua salina disidrata la vite, problema accentuato dal goccia, che accumula sale nella zona delle radici. Il fabbisogno cambia nel ciclo: molta acqua in primavera crea la superficie fogliare, mentre un lieve stress tra allegagione e invaiatura ferma i germogli e favorisce gli acini. L'irrigazione in deficit controllato programma questo stress moderato con il goccia: crescita più controllata, meno acqua e acini più piccoli, quindi più buccia rispetto al succo, più antociani e tannini nei rossi. È più facile in climi con estate secca e suoli sabbiosi o franchi, richiede il monitoraggio dell'umidità del suolo e porta rese più basse, che la qualità deve compensare. L'aridocoltura rinuncia all'irrigazione in zone poco piovose: rese più basse e acqua regolata con cover crop e una buona struttura del suolo.",
         "Là où il pleut peu ou que les sols drainent trop, l'irrigation doit être prévue dès la conception du vignoble, car l'installer ensuite est bien plus compliqué ; certaines AOP européennes l'interdisent ou ne la permettent qu'en urgence. L'eau est rare et réglementée, et les sécheresses en Australie, en Californie et en Afrique du Sud poussent à l'efficacité. Le goutte-à-goutte est de loin le système le plus répandu : des tuyaux le long de chaque rang avec des goutteurs éloignés du tronc pour inciter les racines à explorer ; il permet de doser l'eau par rang ou par parcelle et de distribuer des engrais liquides, mais il coûte à installer, exige une eau propre et de l'entretien car les goutteurs se bouchent, et ne sert à rien contre le gel. La submersion et les rigoles coûtent peu mais gaspillent l'eau et exigent un terrain plat : elles sont courantes en Argentine, où l'eau des Andes abonde. L'aspersion est coûteuse et consomme plus d'eau que le goutte-à-goutte, mais protège des gelées. La qualité de l'eau compte aussi : les solides doivent être filtrés, et une eau salée déshydrate la vigne, problème accentué par le goutte-à-goutte, qui accumule le sel dans la zone racinaire. Les besoins varient au cours du cycle : beaucoup d'eau au printemps crée la surface foliaire, tandis qu'un léger stress entre nouaison et véraison arrête les rameaux et favorise les baies. L'irrigation déficitaire contrôlée programme ce stress modéré au goutte-à-goutte : croissance mieux maîtrisée, moins d'eau et des baies plus petites, donc plus de pellicule par rapport au jus, plus d'anthocyanes et de tanins dans les rouges. Elle est plus facile en climat à été sec et sur sols sableux ou limoneux, exige le suivi de l'humidité du sol et entraîne des rendements plus bas, que la qualité doit compenser. La culture sèche renonce à l'irrigation dans des zones peu arrosées : rendements plus bas, eau régulée par les couverts et une bonne structure du sol.",
         "Where rainfall is low or soils are very free-draining, irrigation should be planned into the vineyard design, since installing it later is much harder; some European PDOs forbid it or allow it only in emergencies. Water is scarce and regulated, and droughts in Australia, California and South Africa push growers towards efficiency. Drip irrigation is by far the commonest system: pipes along each row with drippers set away from the trunk to encourage roots to explore; it allows water to be dosed by row or block and liquid fertiliser to be delivered, but it is costly to install, needs clean water and maintenance because drippers clog, and is no use against frost. Flood and channel irrigation are cheap but waste water and need flat land: they are common in Argentina, where Andean water is plentiful. Overhead sprinklers are expensive and use more water than drip, but protect against frost. Water quality matters too: solids must be filtered, and saline water dehydrates the vine, a problem made worse by drip, which concentrates salt in the root zone. Needs change through the cycle: plenty of water in spring builds leaf area, while mild stress between fruit set and véraison stops shoot growth and favours the berries. Regulated deficit irrigation schedules this moderate stress with drip: better-controlled growth, less water and smaller berries, so a higher skin-to-juice ratio and more anthocyanins and tannins in reds. It is easier in climates with dry summers and on sandy or loam soils, needs soil moisture monitoring and gives lower yields, which quality must make up for. Dry farming does without irrigation in areas of low rainfall: lower yields, with water regulated through cover crops and good soil structure.",
         "Donde llueve poco o los suelos drenan demasiado, el riego debe preverse en el diseño del viñedo, porque instalarlo después es mucho más complicado; algunas DOP europeas lo prohíben o solo lo permiten en emergencias. El agua es escasa y está regulada, y las sequías en Australia, California y Sudáfrica empujan a la eficiencia. El goteo es con mucho el sistema más extendido: tuberías a lo largo de cada fila con goteros alejados del tronco para que las raíces exploren; permite dosificar el agua por fila o parcela y aplicar abonos líquidos, pero es caro de instalar, exige agua limpia y mantenimiento porque los goteros se obstruyen, y no sirve contra la helada. La inundación y los surcos son baratos pero desperdician agua y exigen terreno llano: son comunes en Argentina, donde abunda el agua de los Andes. La aspersión es cara y gasta más agua que el goteo, pero protege de las heladas. También cuenta la calidad del agua: los sólidos deben filtrarse, y el agua salina deshidrata la cepa, problema que el goteo agrava porque acumula sal en la zona de las raíces. Las necesidades cambian a lo largo del ciclo: mucha agua en primavera crea superficie foliar, mientras que un ligero estrés entre cuajado y envero frena los brotes y favorece las bayas. El riego deficitario controlado programa ese estrés moderado con goteo: crecimiento más controlado, menos agua y bayas más pequeñas, es decir, más hollejo respecto al zumo y más antocianos y taninos en los tintos. Es más fácil en climas de verano seco y suelos arenosos o francos, exige medir la humedad del suelo y da rendimientos más bajos, que la calidad debe compensar. El secano prescinde del riego en zonas poco lluviosas: rendimientos más bajos y agua regulada mediante cubiertas y una buena estructura del suelo."])]),
    Q("d1b", ["Il momento e il modo della vendemmia decidono lo stile del vino.", "Le moment et la manière de vendanger décident du style du vin.", "When and how the grapes are picked decides the style of the wine.", "El momento y la forma de vendimiar deciden el estilo del vino."], [
      P(["Spiega come si decide la data di vendemmia.", "Expliquez comment on décide de la date des vendanges.", "Explain how the harvest date is decided.", "Explica cómo se decide la fecha de vendimia."], 6,
        ["un tempo regola dei 100 giorni dalla fioritura e alcol potenziale, per esempio 9,5–11% nei climi freschi; oggi conta anche la maturità di aromi e tannini; zucchero con il rifrattometro, di solito 19–25 °Brix per i vini secchi; acidità per titolazione e pH; aromi e tannini assaggiando le uve; nuove tecniche di spettroscopia; minaccia di pioggia: vendemmiare uve meno mature o rischiare diluizione, spaccature e marciume; vini dolci: vendemmia tardiva, passaggi ripetuti per la botrite, Icewine sotto −8 °C",
         "autrefois règle des 100 jours après la floraison et alcool potentiel, par exemple 9,5–11 % en climat frais ; aujourd'hui compte aussi la maturité des arômes et des tanins ; sucre au réfractomètre, en général 19–25 °Brix pour les vins secs ; acidité par titrage et pH ; arômes et tanins en goûtant les raisins ; nouvelles techniques de spectroscopie ; menace de pluie : vendanger des raisins moins mûrs ou risquer dilution, éclatement et pourriture ; vins doux : vendange tardive, tries successives pour le botrytis, Icewine sous −8 °C",
         "formerly the 100-days-from-flowering rule and potential alcohol, for example 9.5–11% in cool climates; today aroma and tannin ripeness also count; sugar with a refractometer, usually 19–25 °Brix for dry wines; acidity by titration and pH; aromas and tannins by tasting the grapes; newer spectroscopy techniques; threat of rain: pick less ripe grapes or risk dilution, splitting and rot; sweet wines: late harvest, repeated passes for botrytis, Icewine below −8 °C",
         "antes la regla de los 100 días desde la floración y el alcohol potencial, por ejemplo 9,5–11 % en climas frescos; hoy cuenta también la madurez de aromas y taninos; azúcar con refractómetro, normalmente 19–25 °Brix para vinos secos; acidez por valoración y pH; aromas y taninos catando la uva; nuevas técnicas de espectroscopia; amenaza de lluvia: vendimiar uva menos madura o arriesgarse a dilución, rajado y podredumbre; vinos dulces: vendimia tardía, pasadas sucesivas para la botritis, Icewine por debajo de −8 °C"],
        ["In passato si vendemmiava circa 100 giorni dopo l'inizio della fioritura e, in Europa, quando l'alcol potenziale raggiungeva un certo livello: nei climi freschi 9,5–11%, con minimi di legge come 9,5% per il Petit Chablis e 10% per il Chablis. Oggi un clima più caldo e una viticoltura migliore permettono di puntare anche sulla maturità di aromi e tannini. Il viticoltore misura lo zucchero con il rifrattometro (per i vini secchi di solito 19–25 °Brix, pari a circa 11–15% di alcol), l'acidità per titolazione e il pH, e soprattutto assaggia le uve per giudicare aromi e tannini; nuovi strumenti a spettroscopia danno più parametri insieme. Su tutto pesa il meteo: se è prevista pioggia bisogna scegliere tra vendemmiare uve meno mature o rischiare diluizione, acini spaccati e marciume. Per alcuni vini dolci la data è decisiva: vendemmie tardive, passaggi ripetuti per scegliere gli acini botritizzati, Icewine raccolto solo sotto una certa temperatura (−8 °C in Canada). Il dibattito sulla «hang time» prolungata riguarda il rischio di vini troppo alcolici e poco freschi.",
         "Autrefois, on vendangeait environ 100 jours après le début de la floraison et, en Europe, quand l'alcool potentiel atteignait un certain niveau : 9,5–11 % en climat frais, avec des minimums légaux comme 9,5 % pour le Petit Chablis et 10 % pour le Chablis. Aujourd'hui, un climat plus chaud et une meilleure viticulture permettent de viser aussi la maturité des arômes et des tanins. Le viticulteur mesure le sucre au réfractomètre (en général 19–25 °Brix pour les vins secs, soit environ 11–15 % d'alcool), l'acidité par titrage et le pH, et surtout goûte les raisins pour juger arômes et tanins ; de nouveaux instruments de spectroscopie donnent plusieurs paramètres à la fois. La météo pèse sur tout : si la pluie est annoncée, il faut choisir entre vendanger des raisins moins mûrs ou risquer dilution, baies éclatées et pourriture. Pour certains vins doux, la date est décisive : vendanges tardives, tries successives pour choisir les baies botrytisées, Icewine récolté seulement sous une certaine température (−8 °C au Canada). Le débat sur une « hang time » prolongée porte sur le risque de vins trop alcooleux et peu frais.",
         "In the past, grapes were picked about 100 days after the start of flowering and, in Europe, when potential alcohol reached a set level: 9.5–11% in cool climates, with legal minimums such as 9.5% for Petit Chablis and 10% for Chablis. Today a warmer climate and better viticulture allow growers to aim for aroma and tannin ripeness as well. They measure sugar with a refractometer (usually 19–25 °Brix for dry wines, about 11–15% alcohol), acidity by titration and pH, and above all taste the grapes to judge aromas and tannins; newer spectroscopy tools give several readings at once. Weather overrides everything: if rain is forecast, growers must choose between picking less ripe grapes and risking dilution, split berries and rot. For some sweet wines the date is decisive: late harvests, repeated passes to select botrytised berries, Icewine picked only below a set temperature (−8 °C in Canada). The debate on extended hang time concerns the risk of over-alcoholic wines lacking freshness.",
         "Antes se vendimiaba unos 100 días después del inicio de la floración y, en Europa, cuando el alcohol potencial alcanzaba un nivel determinado: 9,5–11 % en climas frescos, con mínimos legales como el 9,5 % del Petit Chablis y el 10 % del Chablis. Hoy un clima más cálido y una viticultura mejor permiten buscar también la madurez de aromas y taninos. El viticultor mide el azúcar con el refractómetro (para vinos secos normalmente 19–25 °Brix, unos 11–15 % de alcohol), la acidez por valoración y el pH, y sobre todo cata la uva para juzgar aromas y taninos; nuevos instrumentos de espectroscopia dan varios parámetros a la vez. La meteorología pesa sobre todo: si se prevé lluvia hay que elegir entre vendimiar uva menos madura o arriesgarse a dilución, bayas rajadas y podredumbre. En algunos vinos dulces la fecha es decisiva: vendimias tardías, pasadas sucesivas para elegir las bayas botritizadas, Icewine recogido solo por debajo de cierta temperatura (−8 °C en Canadá). El debate sobre la «hang time» prolongada se centra en el riesgo de vinos demasiado alcohólicos y poco frescos."]),
      P(["Confronta vendemmia a macchina e a mano per costi, qualità e stili di vino.", "Comparez vendange mécanique et manuelle pour les coûts, la qualité et les styles de vin.", "Compare machine and hand harvesting in terms of cost, quality and wine style.", "Compara la vendimia a máquina y a mano en costes, calidad y estilos de vino."], 9,
        ["macchina: scelta normale per vini economici e medi e grandi volumi, vigneti progettati per la meccanizzazione; molto più veloce e economica, circa un terzo del costo in California; niente problemi di manodopera; di notte, uve fino a 15 °C più fresche: meno ossidazione e alterazioni, aromi freschi, meno refrigerazione; migliorie: cernita prima, macchine a scuotimento più delicate, cernita ottica, solfitazione in macchina, cernita in cantina; limiti: meno delicata, acini rotti, ossidazione ed estrazione, niente grappoli interi; non adatta a pendii, piccoli vigneti, varietà miste, viti ad alberello; investimento alto o noleggio conteso; mano: cernita grappolo per grappolo, pendii e filari irregolari; cassette da 10–15 kg, acini intatti; più cara, serve manodopera affidabile e formata, di giorno al caldo; obbligatoria per pressatura a grappolo intero degli spumanti, macerazione carbonica, vendemmie selettive come i TBA, pendii come il Douro",
         "machine : choix normal pour les vins bon marché et moyens et les gros volumes, vignobles conçus pour la mécanisation ; beaucoup plus rapide et moins chère, environ un tiers du coût en Californie ; pas de problème de main-d'œuvre ; de nuit, raisins jusqu'à 15 °C plus frais : moins d'oxydation et d'altérations, arômes frais, moins de réfrigération ; améliorations : tri préalable, machines à secouement plus douces, tri optique, sulfitage dans la machine, tri au chai ; limites : moins douce, baies éclatées, oxydation et extraction, pas de grappes entières ; inadaptée aux pentes, petites vignes, cépages mélangés, vignes en gobelet ; gros investissement ou location disputée ; main : tri grappe par grappe, pentes et rangs irréguliers ; cagettes de 10–15 kg, baies intactes ; plus chère, main-d'œuvre fiable et formée, de jour à la chaleur ; obligatoire pour le pressurage en grappes entières des effervescents, la macération carbonique, les tries sélectives comme les TBA, les pentes comme le Douro",
         "machine: the norm for inexpensive and mid-priced wines and large volumes, vineyards designed for mechanisation; much faster and cheaper, about one third of the cost in California; no labour problems; at night, grapes up to 15 °C cooler: less oxidation and spoilage, fresh aromas, less refrigeration; improvements: sorting beforehand, gentler shaking machines, optical sorting, SO₂ in the machine, sorting at the winery; limits: less gentle, split berries, oxidation and extraction, no whole bunches; unsuitable for slopes, small plots, mixed varieties, bush vines; big investment or contested hire; hand: selection bunch by bunch, slopes and irregular rows; crates of 10–15 kg, berries intact; dearer, needs reliable trained labour, in daylight and heat; required for whole bunch pressing of sparkling wine, carbonic maceration, selective picking such as TBA, steep slopes such as the Douro",
         "máquina: la norma para vinos económicos y medios y grandes volúmenes, viñedos diseñados para mecanizar; mucho más rápida y barata, alrededor de un tercio del coste en California; sin problemas de mano de obra; de noche, uva hasta 15 °C más fresca: menos oxidación y alteraciones, aromas frescos, menos refrigeración; mejoras: selección previa, máquinas de sacudida más suaves, selección óptica, sulfitado en la máquina, selección en bodega; límites: menos suave, bayas rotas, oxidación y extracción, sin racimos enteros; no apta para pendientes, parcelas pequeñas, variedades mezcladas, vasos; gran inversión o alquiler disputado; mano: selección racimo a racimo, pendientes y filas irregulares; cajas de 10–15 kg, bayas intactas; más cara, mano de obra fiable y formada, de día con calor; obligatoria para el prensado de racimo entero de espumosos, la maceración carbónica, vendimias selectivas como los TBA, pendientes como el Duero"],
        ["La vendemmia meccanica è diventata la norma per i vini economici e di prezzo medio e per le grandi produzioni, soprattutto nei vigneti progettati per le macchine: filari regolari, spazio di manovra, terreno piano o con pendenza lieve. È molto più rapida ed economica (in California circa un terzo del costo della vendemmia manuale), non dipende dalla disponibilità di manodopera e può avvenire di notte, con uve fino a 15 °C più fresche: meno ossidazione e alterazioni microbiche, aromi più freschi nei bianchi e risparmio di refrigerazione; inoltre si può vendemmiare rapidamente al momento giusto. La qualità è migliorata grazie alla cernita manuale prima del passaggio, alle macchine a scuotimento più delicate e selettive, ai modelli con cernita ottica e solfitazione a bordo e a una cernita rigorosa in cantina. Restano limiti: la macchina scuote gli acini dal raspo, li rompe e libera succo, con rischio di ossidazione ed estrazione, e non dà grappoli interi; non conviene ai piccoli vigneti, non funziona su pendii, viti ad alberello senza spalliera o parcelle con varietà miste, richiede un operatore abile e un forte investimento, o un noleggio conteso nei giorni migliori. La vendemmia manuale permette di scegliere grappolo per grappolo, scartando uve malate o non mature, di lavorare su pendii e filari irregolari e, con cassette da 10–15 kg, di portare in cantina acini intatti. Costa però di più nei vigneti medi e grandi, richiede manodopera affidabile, formata e supervisionata e si svolge di giorno, al caldo. È indispensabile per gli spumanti di qualità pressati a grappolo intero, per la macerazione carbonica, per vendemmie selettive come i Trockenbeerenauslese e per i pendii come quelli del Douro.",
         "La vendange mécanique est devenue la norme pour les vins bon marché et de prix moyen et pour les gros volumes, surtout dans les vignobles conçus pour les machines : rangs réguliers, espace de manœuvre, terrain plat ou en pente douce. Elle est beaucoup plus rapide et économique (en Californie, environ un tiers du coût de la vendange manuelle), ne dépend pas de la main-d'œuvre disponible et peut se faire de nuit, avec des raisins jusqu'à 15 °C plus frais : moins d'oxydation et d'altérations microbiennes, des arômes plus frais pour les blancs et une économie de réfrigération ; on peut en outre vendanger vite au bon moment. La qualité a progressé grâce au tri manuel avant le passage, aux machines à secouement plus douces et sélectives, aux modèles avec tri optique et sulfitage embarqué et à un tri rigoureux au chai. Des limites demeurent : la machine détache les baies de la rafle, les éclate et libère du jus, avec un risque d'oxydation et d'extraction, et ne donne pas de grappes entières ; elle ne convient pas aux petites vignes, ne fonctionne pas sur les pentes, les vignes en gobelet sans palissage ou les parcelles de cépages mélangés, exige un conducteur habile et un gros investissement, ou une location disputée aux meilleurs jours. La vendange manuelle permet de trier grappe par grappe, en écartant les raisins malades ou pas mûrs, de travailler sur les pentes et les rangs irréguliers et, avec des cagettes de 10–15 kg, d'apporter au chai des baies intactes. Elle coûte cependant plus cher dans les vignes moyennes et grandes, exige une main-d'œuvre fiable, formée et encadrée, et se fait de jour, à la chaleur. Elle est indispensable pour les effervescents de qualité pressés en grappes entières, pour la macération carbonique, pour les tries sélectives comme les Trockenbeerenauslese et pour les pentes comme celles du Douro.",
         "Machine harvesting has become the norm for inexpensive and mid-priced wines and for large-scale production, especially in vineyards designed for machines: even rows, turning space, flat land or gentle slopes. It is much faster and cheaper (in California about one third of the cost of hand picking), does not depend on available labour and can be done at night, with grapes up to 15 °C cooler: less oxidation and microbial spoilage, fresher aromas in whites and savings on refrigeration; picking can also be done quickly at the right moment. Quality has improved thanks to hand sorting before the machine passes, gentler and more selective shaking machines, models with optical sorting and on-board SO₂ addition, and rigorous sorting at the winery. Limits remain: the machine shakes berries off the stems, splits them and releases juice, risking oxidation and extraction, and gives no whole bunches; it does not suit small vineyards, does not work on slopes, untrellised bush vines or plots of mixed varieties, needs a skilled operator and a large investment, or a hire that is in demand on the best days. Hand picking allows selection bunch by bunch, discarding diseased or unripe fruit, works on slopes and irregular rows and, with crates of 10–15 kg, brings intact berries to the winery. It is, however, dearer in medium and large vineyards, needs reliable, trained and supervised labour, and is done in daylight, in the heat. It is essential for quality sparkling wines that are whole-bunch pressed, for carbonic maceration, for selective picking such as Trockenbeerenauslese and for steep slopes such as the Douro.",
         "La vendimia mecánica se ha convertido en la norma para vinos económicos y de precio medio y para grandes volúmenes, sobre todo en viñedos diseñados para las máquinas: filas regulares, espacio para girar, terreno llano o de pendiente suave. Es mucho más rápida y barata (en California, alrededor de un tercio del coste de la vendimia manual), no depende de la mano de obra disponible y puede hacerse de noche, con uva hasta 15 °C más fresca: menos oxidación y alteraciones microbianas, aromas más frescos en los blancos y ahorro de refrigeración; además se puede vendimiar deprisa en el momento justo. La calidad ha mejorado gracias a la selección manual antes del paso de la máquina, a las máquinas de sacudida más suaves y selectivas, a los modelos con selección óptica y sulfitado a bordo y a una selección rigurosa en bodega. Quedan límites: la máquina sacude las bayas del raspón, las rompe y libera zumo, con riesgo de oxidación y extracción, y no da racimos enteros; no conviene a parcelas pequeñas, no funciona en pendientes, en vasos sin espaldera ni en parcelas con variedades mezcladas, exige un operador hábil y una gran inversión, o un alquiler disputado en los mejores días. La vendimia manual permite seleccionar racimo a racimo, descartando uva enferma o inmadura, trabajar en pendientes y filas irregulares y, con cajas de 10–15 kg, llevar a la bodega bayas intactas. Pero es más cara en viñedos medianos y grandes, exige mano de obra fiable, formada y supervisada, y se hace de día, con calor. Es imprescindible para los espumosos de calidad prensados en racimo entero, para la maceración carbónica, para vendimias selectivas como los Trockenbeerenauslese y para pendientes como las del Duero."])])
  ]
};
